package com.adamk33n3r.runelite.watchdog;

import com.adamk33n3r.nodegraph.nodes.TriggerNode;
import com.adamk33n3r.runelite.watchdog.alerts.AdvancedAlert;
import com.adamk33n3r.runelite.watchdog.alerts.SpawnedAlert;
import com.adamk33n3r.runelite.watchdog.alerts.SpawnedAlert.SpawnedDespawned;
import com.adamk33n3r.runelite.watchdog.alerts.SpawnedAlert.SpawnedType;

import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;

import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.stream.Stream;

import static org.mockito.ArgumentMatchers.*;

@RunWith(MockitoJUnitRunner.class)
public class SpawnedAlertLegacyPathTest extends AlertTestBase {

    @InjectMocks
    EventHandler eventHandler;

    private static final WorldPoint PLAYER_LOC = new WorldPoint(3200, 3200, 0);

    @Before
    public void setup() {
        Mockito.doNothing().when(this.watchdogPlugin).processAlert(any(), any(), anyBoolean());
        Player player = Mockito.mock(Player.class);
        Mockito.when(player.getWorldLocation()).thenReturn(PLAYER_LOC);
        Mockito.when(this.client.getLocalPlayer()).thenReturn(player);
        // batchSpawnedEvents() defaults to false on a Mockito mock — no stub needed
    }

    // region Helpers

    private SpawnedAlert makeNpcAlert(String pattern) {
        SpawnedAlert alert = new SpawnedAlert("test");
        alert.setPattern(pattern);
        alert.setSpawnedType(SpawnedType.NPC);
        alert.setSpawnedDespawned(SpawnedDespawned.SPAWNED);
        return alert;
    }

    private void mockAlertManager(SpawnedAlert alert) {
        Mockito.doAnswer(inv -> {
            Class<?> clazz = inv.getArgument(0);
            if (clazz == SpawnedAlert.class) return Stream.of(alert);
            return Stream.empty();
        }).when(this.alertManager).getAllEnabledAlertsOfType(any());
        Mockito.doReturn(true).when(this.alertManager).hasEnabledAlertsOfType(SpawnedAlert.class);
    }

    private void fireNpc(String name, int id) {
        this.eventHandler.onSpawned(name, id, PLAYER_LOC, SpawnedDespawned.SPAWNED, SpawnedType.NPC, EventHandler.ALWAYS);
    }

    // endregion

    @Test
    public void singleSpawn_firesImmediately() {
        SpawnedAlert alert = this.makeNpcAlert("Cow");
        this.mockAlertManager(alert);

        this.fireNpc("Cow", 1);

        Mockito.verify(this.watchdogPlugin).processAlert(eq(alert), any(), eq(false));
    }

    @Test
    public void batchOfSpawns_firesPerEvent() {
        SpawnedAlert alert = this.makeNpcAlert("Cow");
        alert.setDebounceTime(0);
        this.mockAlertManager(alert);

        for (int i = 0; i < 30; i++) {
            this.fireNpc("Cow", i);
        }

        Mockito.verify(this.watchdogPlugin, Mockito.times(30)).processAlert(eq(alert), any(), eq(false));
    }

    @Test
    public void batchOfSpawns_withDebounce_firesOnce() {
        SpawnedAlert alert = this.makeNpcAlert("Cow");
        alert.setDebounceTime(500);
        this.mockAlertManager(alert);

        for (int i = 0; i < 30; i++) {
            this.fireNpc("Cow", i);
        }

        Mockito.verify(this.watchdogPlugin, Mockito.times(1)).processAlert(eq(alert), any(), eq(false));
    }

    @Test
    public void noEnabledAlerts_fastPathSkips() {
        Mockito.doReturn(false).when(this.alertManager).hasEnabledAlertsOfType(any());

        this.fireNpc("Cow", 1);

        Mockito.verify(this.watchdogPlugin, Mockito.never()).processAlert(any(), any(), anyBoolean());
    }

    @Test
    public void disabledAlert_notFired() {
        SpawnedAlert alert = this.makeNpcAlert("Cow");
        alert.setEnabled(false);
        this.mockAlertManager(alert);

        this.fireNpc("Cow", 1);

        Mockito.verify(this.watchdogPlugin, Mockito.never()).processAlert(any(), any(), anyBoolean());
    }

    @Test
    public void advancedAlertTrigger_firesPerEvent_legacy() {
        SpawnedAlert innerAlert = this.makeNpcAlert("*");
        TriggerNode triggerNode = new TriggerNode(innerAlert);

        AdvancedAlert advSpy = Mockito.spy(new AdvancedAlert("adv test"));
        advSpy.getGraph().add(triggerNode);

        Mockito.doAnswer(inv -> {
            Class<?> clazz = inv.getArgument(0);
            if (clazz == AdvancedAlert.class) return Stream.of(advSpy);
            return Stream.empty();
        }).when(this.alertManager).getAllEnabledAlertsOfType(any());
        Mockito.doReturn(false).when(this.alertManager).hasEnabledAlertsOfType(SpawnedAlert.class);
        Mockito.doReturn(true).when(this.alertManager).hasEnabledAlertsOfType(AdvancedAlert.class);

        this.fireNpc("Goblin", 1);
        this.fireNpc("Goblin", 2);
        this.fireNpc("Goblin", 3);

        Mockito.verify(advSpy, Mockito.times(3)).fireTriggerNode(eq(triggerNode), any());
    }

    @Test
    public void distanceFilter_outOfRange_doesNotFire() {
        SpawnedAlert alert = this.makeNpcAlert("*");
        alert.setDistance(5);
        this.mockAlertManager(alert);

        WorldPoint farLoc = new WorldPoint(3215, 3215, 0);
        this.eventHandler.onSpawned("Goblin", 1, farLoc, SpawnedDespawned.SPAWNED, SpawnedType.NPC, EventHandler.ALWAYS);

        Mockito.verify(this.watchdogPlugin, Mockito.never()).processAlert(any(), any(), anyBoolean());
    }

    @Test
    public void distanceFilter_withinRange_fires() {
        SpawnedAlert alert = this.makeNpcAlert("*");
        alert.setDistance(5);
        this.mockAlertManager(alert);

        this.fireNpc("Goblin", 1);

        Mockito.verify(this.watchdogPlugin).processAlert(eq(alert), any(), eq(false));
    }
}

package com.adamk33n3r.runelite.watchdog;

import com.adamk33n3r.nodegraph.nodes.ActionNode;
import com.adamk33n3r.nodegraph.nodes.TriggerNode;
import com.adamk33n3r.nodegraph.nodes.utility.NoteNode;
import com.adamk33n3r.runelite.watchdog.alerts.AdvancedAlert;
import com.adamk33n3r.runelite.watchdog.alerts.Alert;
import com.adamk33n3r.runelite.watchdog.alerts.ChatAlert;
import com.adamk33n3r.runelite.watchdog.notifications.ScreenFlash;

import org.junit.Assert;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import javax.inject.Inject;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;

@RunWith(MockitoJUnitRunner.class)
public class AdvancedAlertTest extends TestBase {

    @Inject
    AlertManager alertManager;

    @Test
    public void triggerType_hasAdvancedAlertEntry() {
        Assert.assertEquals("Advanced Alert", TriggerType.ADVANCED_ALERT.getName());
        Assert.assertEquals(AdvancedAlert.class, TriggerType.ADVANCED_ALERT.getImplClass());
    }

    @Test
    public void gson_roundTrip_preservesName() {
        AdvancedAlert alert = new AdvancedAlert("My Graph Alert");

        String json = alertManager.getGson().toJson(alert, Alert.class);
        Alert deserialized = alertManager.getGson().fromJson(json, Alert.class);

        Assert.assertTrue(deserialized instanceof AdvancedAlert);
        Assert.assertEquals("My Graph Alert", deserialized.getName());
    }

    @Test
    public void gson_roundTrip_preservesTriggerNode() {
        AdvancedAlert alert = new AdvancedAlert("Graph Alert");
        TriggerNode trigger = new TriggerNode(new ChatAlert("harvest"));
        alert.getGraph().add(trigger);

        String json = alertManager.getGson().toJson(alert, Alert.class);
        AdvancedAlert loaded = (AdvancedAlert) alertManager.getGson().fromJson(json, Alert.class);

        Assert.assertEquals(1, loaded.getGraph().getNodes().size());
        Assert.assertTrue(loaded.getGraph().getNodes().get(0) instanceof TriggerNode);
        TriggerNode loadedTrigger = (TriggerNode) loaded.getGraph().getNodes().get(0);
        Assert.assertTrue(loadedTrigger.getAlert() instanceof ChatAlert);
        Assert.assertEquals("harvest", loadedTrigger.getAlert().getName());
    }

    @Test
    public void gson_roundTrip_preservesConnection() {
        AdvancedAlert alert = new AdvancedAlert("Graph Alert");
        TriggerNode trigger = new TriggerNode(new ChatAlert("test"));
        ActionNode notifNode = new ActionNode(new ScreenFlash());
        alert.getGraph().add(trigger);
        alert.getGraph().add(notifNode);
        alert.getGraph().connect(trigger.getExec(), notifNode.getExec());

        String json = alertManager.getGson().toJson(alert, Alert.class);
        AdvancedAlert loaded = (AdvancedAlert) alertManager.getGson().fromJson(json, Alert.class);

        Assert.assertEquals(1, loaded.getGraph().getConnections().size());
    }

    @Test
    public void loadAlerts_handlesAdvancedAlertJson() {
        AdvancedAlert alert = new AdvancedAlert("Graph Test");
        alert.getGraph().add(new TriggerNode(new ChatAlert("harvest")));
        String json = "[" + alertManager.getGson().toJson(alert, Alert.class) + "]";

        Mockito.when(configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.ALERTS))
            .thenReturn(json);
        Mockito.when(configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.PLUGIN_VERSION))
            .thenReturn(pluginVersion);

        alertManager.loadAlerts();

        Assert.assertEquals(1, alertManager.getAlerts().size());
        Assert.assertTrue(alertManager.getAlerts().get(0) instanceof AdvancedAlert);
        AdvancedAlert loaded = (AdvancedAlert) alertManager.getAlerts().get(0);
        Assert.assertEquals("Graph Test", loaded.getName());
        Assert.assertEquals(1, loaded.getGraph().getNodes().size());
    }

    @Test
    public void loadAlerts_advancedAlertWithRegularAlerts() {
        AdvancedAlert adv = new AdvancedAlert("Advanced");
        ChatAlert chat = new ChatAlert("Regular");
        chat.setMessage("hello*");
        String advJson = alertManager.getGson().toJson(adv, Alert.class);
        String chatJson = alertManager.getGson().toJson(chat, Alert.class);
        String json = "[" + advJson + "," + chatJson + "]";

        Mockito.when(configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.ALERTS))
            .thenReturn(json);
        Mockito.when(configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.PLUGIN_VERSION))
            .thenReturn(pluginVersion);

        alertManager.loadAlerts();

        Assert.assertEquals(2, alertManager.getAlerts().size());
        Assert.assertTrue(alertManager.getAlerts().get(0) instanceof AdvancedAlert);
        Assert.assertTrue(alertManager.getAlerts().get(1) instanceof ChatAlert);
    }

    @Test
    public void newAdvancedAlert_hasExactlyOneWelcomeNote() {
        AdvancedAlert alert = this.alertManager.createAlert(AdvancedAlert.class);
        long noteCount = alert.getGraph().getNodesOfType(NoteNode.class).count();
        assertEquals(1, noteCount);
    }

    @Test
    public void welcomeNote_hasNonEmptyText() {
        AdvancedAlert alert = this.alertManager.createAlert(AdvancedAlert.class);
        NoteNode note = alert.getGraph().getNodesOfType(NoteNode.class).findFirst().orElseThrow();
        assertFalse(note.getNote().getValue().isEmpty());
    }

    @Test
    public void deserializedAdvancedAlert_doesNotDuplicateNote() {
        AdvancedAlert alert = this.alertManager.createAlert(AdvancedAlert.class);
        String json = this.alertManager.getGson().toJson(alert, AdvancedAlert.class);
        AdvancedAlert reloaded = this.alertManager.getGson().fromJson(json, AdvancedAlert.class);
        long noteCount = reloaded.getGraph().getNodesOfType(NoteNode.class).count();
        assertEquals(1, noteCount);
    }
}

package com.adamk33n3r.runelite.watchdog;

import com.adamk33n3r.runelite.watchdog.alerts.*;
import com.adamk33n3r.runelite.watchdog.notifications.Notification;
import com.adamk33n3r.runelite.watchdog.notifications.Overlay;

import org.junit.Assert;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mockito;
import org.mockito.junit.MockitoJUnitRunner;

import javax.inject.Inject;
import java.util.List;
import java.util.stream.Stream;

@RunWith(MockitoJUnitRunner.class)
public class AlertManagerTest extends TestBase {

    @Inject
    AlertManager alertManager;

    @Test
    public void test_import() {
        String json = "[{\"type\":\"ChatAlert\",\"message\":\"*is ready to harvest*\",\"regexEnabled\":false,\"enabled\":true,\"name\":\"Ready to Harvest\",\"debounceTime\":500,\"notifications\":[{\"type\":\"TrayNotification\",\"message\":\"Time to harvest your crops!\",\"fireWhenFocused\":true},{\"type\":\"Sound\",\"path\":\"C:\\\\Users\\\\adamg\\\\Music\\\\airplane_seatbelt.mp3\",\"gain\":10,\"fireWhenFocused\":true},{\"type\":\"TextToSpeech\",\"gain\":5,\"rate\":1,\"voice\":\"GEORGE\",\"source\":\"LEGACY\",\"message\":\"\",\"fireWhenFocused\":true},{\"type\":\"Overhead\",\"displayTime\":3,\"message\":\"\",\"fireWhenFocused\":true}]},{\"type\":\"NotificationFiredAlert\",\"message\":\"You are now out of combat!\",\"regexEnabled\":false,\"enabled\":true,\"name\":\"Out of Combat\",\"debounceTime\":0,\"notifications\":[{\"type\":\"ScreenFlash\",\"color\":\"#46FF0000\",\"flashMode\":\"FLASH\",\"flashDuration\":0,\"fireWhenFocused\":true}]},{\"type\":\"SpawnedAlert\",\"spawnedDespawned\":\"SPAWNED\",\"spawnedType\":\"ITEM\",\"spawnedName\":\"Bones\",\"regexEnabled\":false,\"enabled\":false,\"name\":\"Bones Spawned\",\"debounceTime\":0,\"notifications\":[{\"type\":\"SoundEffect\",\"soundID\":3925,\"gain\":10,\"fireWhenFocused\":true},{\"type\":\"ScreenFlash\",\"color\":\"#46FF0000\",\"flashMode\":\"FLASH\",\"flashDuration\":0,\"fireWhenFocused\":true}]},{\"type\":\"SpawnedAlert\",\"spawnedDespawned\":\"SPAWNED\",\"spawnedType\":\"NPC\",\"spawnedName\":\"Gee\",\"regexEnabled\":false,\"enabled\":false,\"name\":\"NPC Spawn\",\"debounceTime\":0,\"notifications\":[{\"type\":\"Overhead\",\"displayTime\":3,\"message\":\"The dude is here\",\"fireWhenFocused\":true},{\"type\":\"TextToSpeech\",\"gain\":10,\"rate\":1,\"voice\":\"GEORGE\",\"source\":\"LEGACY\",\"message\":\"\",\"fireWhenFocused\":true}]},{\"type\":\"SpawnedAlert\",\"spawnedDespawned\":\"SPAWNED\",\"spawnedType\":\"GAME_OBJECT\",\"spawnedName\":\"Tree\",\"regexEnabled\":false,\"enabled\":false,\"name\":\"New Spawned Alert\",\"debounceTime\":0,\"notifications\":[{\"type\":\"Overhead\",\"displayTime\":3,\"message\":\"CHOP THE TREE\",\"fireWhenFocused\":true},{\"type\":\"SoundEffect\",\"soundID\":3924,\"gain\":10,\"fireWhenFocused\":true}]},{\"type\":\"ChatAlert\",\"message\":\"\",\"regexEnabled\":false,\"enabled\":true,\"name\":\"test 11labs lag\",\"debounceTime\":0,\"notifications\":[{\"type\":\"TextToSpeech\",\"gain\":10,\"rate\":1,\"voice\":\"GEORGE\",\"source\":\"LEGACY\",\"message\":\"this is a test\",\"fireWhenFocused\":true}]}]";
        Mockito.when(this.configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.ALERTS))
            .thenReturn(json);
        Mockito.when(this.configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.PLUGIN_VERSION))
            .thenReturn(this.pluginVersion);
        Assert.assertEquals(0, alertManager.getAlerts().size());
        alertManager.loadAlerts();
        Assert.assertEquals(6, alertManager.getAlerts().size());
    }

    @Test
    public void test_upgrade() {
        String json = "[{\"type\":\"ChatAlert\",\"message\":\"\",\"regexEnabled\":false,\"enabled\":true,\"name\":\"Upgrade Test\",\"debounceTime\":0,\"notifications\":[{\"type\":\"Overlay\",\"color\":\"#46FF0000\",\"sticky\":false,\"timeToLive\":5,\"imagePath\":\"\",\"message\":\"Overlay notification\",\"fireWhenFocused\":true}]}]";
        Mockito.when(this.configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.ALERTS))
            .thenReturn(json);
        Mockito.when(this.configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.PLUGIN_VERSION))
            .thenReturn("2.12.0");
        alertManager.loadAlerts();
        Alert alert = alertManager.getAlerts().get(0);
        Assert.assertTrue(alert instanceof ChatAlert);
        Notification notification = alert.getNotifications().get(0);
        Assert.assertTrue(notification instanceof Overlay);
        Assert.assertNotNull(((Overlay) notification).getTextColor());
    }

    @Test
    public void getAllEnabledAlertsOfType_returnsEmpty_whenAdvancedAlertsDisabled() {
        // watchdogConfig.enableAdvancedAlerts() returns false by default (Mockito mock)
        AdvancedAlert adv = new AdvancedAlert("Test");
        adv.setEnabled(true);
        alertManager.getAlerts().add(adv);

        Stream<AdvancedAlert> result = alertManager.getAllEnabledAlertsOfType(AdvancedAlert.class);
        Assert.assertEquals(0, result.count());
    }

    @Test
    public void getAllEnabledAlertsOfType_returnsAlerts_whenAdvancedAlertsEnabled() {
        Mockito.when(this.watchdogConfig.enableAdvancedAlerts()).thenReturn(true);
        AdvancedAlert adv = new AdvancedAlert("Test");
        adv.setEnabled(true);
        alertManager.getAlerts().add(adv);

        Stream<AdvancedAlert> result = alertManager.getAllEnabledAlertsOfType(AdvancedAlert.class);
        Assert.assertEquals(1, result.count());
    }

    @Test
    public void getAllEnabledAlertsOfType_unaffectedForOtherTypes_whenAdvancedAlertsDisabled() {
        // watchdogConfig.enableAdvancedAlerts() returns false by default (Mockito mock)
        ChatAlert chat = new ChatAlert("hello");
        chat.setEnabled(true);
        alertManager.getAlerts().add(chat);

        Stream<ChatAlert> result = alertManager.getAllEnabledAlertsOfType(ChatAlert.class);
        Assert.assertEquals(1, result.count());
    }

    @Test
    public void hasEnabledAlertsOfType_returnsFalse_whenAdvancedAlertsDisabled() {
        // watchdogConfig.enableAdvancedAlerts() returns false by default (Mockito mock)
        AdvancedAlert adv = new AdvancedAlert("Test");
        adv.setEnabled(true);
        alertManager.getAlerts().add(adv);

        Assert.assertFalse(alertManager.hasEnabledAlertsOfType(AdvancedAlert.class));
    }

    @Test
    public void hasEnabledAlertsOfType_returnsTrue_whenAdvancedAlertsEnabled() {
        Mockito.when(this.watchdogConfig.enableAdvancedAlerts()).thenReturn(true);
        AdvancedAlert adv = new AdvancedAlert("Test");
        adv.setEnabled(true);
        alertManager.getAlerts().add(adv);

        Assert.assertTrue(alertManager.hasEnabledAlertsOfType(AdvancedAlert.class));
    }

    @Test
    public void test_upgrade_3_14_0() {
        String json = "[" +
            "{\"type\":\"ChatAlert\",\"message\":\"*the end.\",\"regexEnabled\":false,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +
            "{\"type\":\"ChatAlert\",\"message\":\"The beginning*\",\"regexEnabled\":false,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +
            "{\"type\":\"ChatAlert\",\"message\":\"The beginning and the end.\",\"regexEnabled\":false,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +
            "{\"type\":\"PlayerChatAlert\",\"message\":\"*and*\",\"regexEnabled\":false,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +

            "{\"type\":\"ChatAlert\",\"message\":\"The beginning and the end\\\\.\",\"regexEnabled\":true,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +
            "{\"type\":\"ChatAlert\",\"message\":\".*the end.\",\"regexEnabled\":true,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +
            "{\"type\":\"ChatAlert\",\"message\":\"^The beginning and the end\\\\.\",\"regexEnabled\":true,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +
            "{\"type\":\"ChatAlert\",\"message\":\"The beginning and the end\\\\.$\",\"regexEnabled\":true,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +
            "{\"type\":\"ChatAlert\",\"message\":\"^The beginning and the end\\\\.$\",\"regexEnabled\":true,\"gameMessageType\":\"ANY\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}," +

            "{\"type\":\"OverheadTextAlert\",\"regexEnabled\":false,\"message\":\"The beginning and the end.\",\"npcRegexEnabled\":false,\"npcName\":\"ali*\",\"enabled\":true,\"name\":\"v3.14.0 Upgrade Test\"}" +
        "]";
        Mockito.when(this.configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.ALERTS))
            .thenReturn(json);
        Mockito.when(this.configManager.getConfiguration(WatchdogConfig.CONFIG_GROUP_NAME, WatchdogConfig.PLUGIN_VERSION))
            .thenReturn("3.13.0");
        alertManager.loadAlerts();
        alertManager.getAlerts().forEach(alert -> {
            Assert.assertTrue(alert instanceof RegexMatcher);
            String pattern = ((RegexMatcher) alert).getPattern();
            // Test the specific case where the glob is wrapped in * on both sides
            if (alert instanceof PlayerChatAlert) {
                Assert.assertEquals("and", ((PlayerChatAlert) alert).getPattern());
            } else {
                Assert.assertTrue(pattern.startsWith("^") && pattern.endsWith("$"));
            }
            if (alert instanceof OverheadTextAlert) {
                Assert.assertTrue(((OverheadTextAlert) alert).isNpcRegexEnabled());
                Assert.assertEquals("^ali.*$", ((OverheadTextAlert) alert).getNpcName());
            }
        });
    }
}

package com.adamk33n3r.runelite.watchdog;

import com.adamk33n3r.nodegraph.Graph;
import com.adamk33n3r.nodegraph.nodes.ActionNode;
import com.adamk33n3r.nodegraph.nodes.TriggerNode;
import com.adamk33n3r.nodegraph.nodes.flow.DelayNode;
import com.adamk33n3r.runelite.watchdog.alerts.AdvancedAlert;
import com.adamk33n3r.runelite.watchdog.alerts.AlertGroup;
import com.adamk33n3r.runelite.watchdog.alerts.ChatAlert;
import com.adamk33n3r.runelite.watchdog.notifications.GameMessage;
import com.adamk33n3r.runelite.watchdog.serialization.WatchdogGsonFactory;
import com.google.gson.Gson;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Before;
import org.junit.Test;

import java.util.List;
import java.util.stream.Collectors;

import static org.junit.Assert.*;

public class AlertConverterTest {
    private AlertConverter converter;

    @Before
    public void setUp() {
        converter = new AlertConverter(RuneLiteAPI.GSON);
    }

    // --- name ---

    @Test
    public void name_isSuffixedWithAdvanced() {
        assertEquals("My Alert (Advanced)", converter.convert(new ChatAlert("My Alert")).getName());
    }

    // --- alert-level properties ---

    @Test
    public void enabled_false_isCarriedToResult() {
        ChatAlert source = new ChatAlert("Test");
        source.setEnabled(false);
        assertFalse(converter.convert(source).isEnabled());
    }

    @Test
    public void debounceTime_isCarriedToResult() {
        ChatAlert source = new ChatAlert("Test");
        source.setDebounceTime(3000);
        assertEquals(3000, converter.convert(source).getDebounceTime());
    }

    // --- node structure: single alert with no notifications ---

    @Test
    public void singleAlert_noNotifications_producesTriggerNodeOnly() {
        Graph graph = converter.convert(new ChatAlert("Test")).getGraph();

        assertEquals(1, graph.getNodes().size());
        assertTrue(graph.getNodes().get(0) instanceof TriggerNode);
        assertEquals(0, graph.getConnections().size());
    }

    // --- node structure: single alert with notifications ---

    @Test
    public void singleAlert_oneNotification_producesTwoNodesOneConnection() {
        ChatAlert source = new ChatAlert("Test");
        source.getNotifications().add(new GameMessage());
        Graph graph = converter.convert(source).getGraph();

        assertEquals(2, graph.getNodes().size());
        assertTrue(graph.getNodes().get(0) instanceof TriggerNode);
        assertTrue(graph.getNodes().get(1) instanceof ActionNode);
        assertEquals(1, graph.getConnections().size());
    }

    @Test
    public void singleAlert_twoNotifications_producesLinearChain() {
        ChatAlert source = new ChatAlert("Test");
        source.getNotifications().add(new GameMessage());
        source.getNotifications().add(new GameMessage());
        Graph graph = converter.convert(source).getGraph();

        assertEquals(3, graph.getNodes().size());
        assertEquals(2, graph.getConnections().size());
    }

    // --- delay injection ---

    @Test
    public void notification_withDelay_injectsDelayNodeBeforeActionNode() {
        ChatAlert source = new ChatAlert("Test");
        GameMessage delayed = new GameMessage();
        delayed.setDelayMilliseconds(500);
        source.getNotifications().add(delayed);
        Graph graph = converter.convert(source).getGraph();

        assertEquals(3, graph.getNodes().size());
        assertTrue(graph.getNodes().get(0) instanceof TriggerNode);
        assertTrue(graph.getNodes().get(1) instanceof DelayNode);
        assertTrue(graph.getNodes().get(2) instanceof ActionNode);
        assertEquals(2, graph.getConnections().size());
    }

    @Test
    public void notification_withDelay_delayNodeCarriesCorrectValue() {
        ChatAlert source = new ChatAlert("Test");
        GameMessage delayed = new GameMessage();
        delayed.setDelayMilliseconds(750);
        source.getNotifications().add(delayed);
        Graph graph = converter.convert(source).getGraph();

        DelayNode delayNode = (DelayNode) graph.getNodes().get(1);
        assertEquals(750, delayNode.getDelayMs().getValue().intValue());
    }

    @Test
    public void notification_withDelay_delayMillisecondsZeroedOnActionNode() {
        ChatAlert source = new ChatAlert("Test");
        GameMessage delayed = new GameMessage();
        delayed.setDelayMilliseconds(500);
        source.getNotifications().add(delayed);
        Graph graph = converter.convert(source).getGraph();

        ActionNode actionNode = (ActionNode) graph.getNodes().get(2);
        assertEquals(0, actionNode.getNotification().getDelayMilliseconds());
