    @Test
    public void process_cascadesRecursively() {
        Graph graph = new Graph();
        Num num = new Num();
        num.setValue(42);
        Add add = new Add();
        graph.add(num);
        graph.add(add);
        graph.connect(num.getValue(), add.getA());
        graph.connect(num.getValue(), add.getB());

        graph.process(num);

        assertEquals(84, add.getResult().getValue().intValue());
    }

    @Test
    public void graph_executeExecChain_exceptionInActionNode_doesNotKillOtherActions() {
        Graph graph = new Graph();
        TriggerNode trigger = new TriggerNode(new ChatAlert("test"));
        Notification throwingNotif = Mockito.mock(Notification.class);
        Mockito.doThrow(new RuntimeException("boom")).when(throwingNotif).fire(Mockito.any());
        Notification goodNotif = Mockito.mock(Notification.class);
        ActionNode throwingAction = new ActionNode(throwingNotif);
        ActionNode goodAction = new ActionNode(goodNotif);

        graph.add(trigger);
        graph.add(throwingAction);
        graph.add(goodAction);
        graph.connect(trigger.getExec(), throwingAction.getExec());
        graph.connect(trigger.getExec(), goodAction.getExec());

        AtomicReference<Throwable> captured = new AtomicReference<>();
        graph.setOnError(captured::set);

        graph.executeExecChain(trigger, new String[0]);

        Mockito.verify(goodNotif).fire(Mockito.any());
        assertNotNull("onError should have been called", captured.get());
        assertEquals("boom", captured.get().getMessage());
    }

    @Test
    public void advancedAlert_fireTriggerNode_exception_logsToHistoryPanel() throws InterruptedException {
        AdvancedAlert adv = new AdvancedAlert("test");
        Graph graph = adv.getGraph();

        TriggerNode trigger = new TriggerNode(new ChatAlert("test"));
        Notification throwingNotif = Mockito.mock(Notification.class);
        Mockito.doThrow(new RuntimeException("notif-boom")).when(throwingNotif).fire(Mockito.any());
        ActionNode action = new ActionNode(throwingNotif);

        graph.add(trigger);
        graph.add(action);
        graph.connect(trigger.getExec(), action.getExec());

        adv.setErrorHandler((alert, t) -> historyPanel.addError(alert, t));
        adv.fireTriggerNode(trigger, new String[0]);
        Thread.sleep(200);

        Mockito.verify(historyPanel).addError(Mockito.eq(adv), Mockito.any(RuntimeException.class));
    }

    @Test
    public void graph_executeExecChain_exceptionInDelayThread_loggedNotPropagated() throws InterruptedException {
        Graph graph = new Graph();
        TriggerNode trigger = new TriggerNode(new ChatAlert("test"));
        DelayNode delay = new DelayNode();
        delay.getDelayMs().setValue(50);
        Notification throwingNotif = Mockito.mock(Notification.class);
        Mockito.doThrow(new RuntimeException("delay-boom")).when(throwingNotif).fire(Mockito.any());
        ActionNode action = new ActionNode(throwingNotif);

        graph.add(trigger);
        graph.add(delay);
        graph.add(action);
        graph.connect(trigger.getExec(), delay.getExec());
        graph.connect(delay.getExecOut(), action.getExec());

        CountDownLatch errorLatch = new CountDownLatch(1);
        AtomicReference<Throwable> captured = new AtomicReference<>();
        graph.setOnError(t -> {
            captured.set(t);
            errorLatch.countDown();
        });

        graph.executeExecChain(trigger, new String[0]);

        assertTrue("onError should be called after delay", errorLatch.await(500, TimeUnit.MILLISECONDS));
        assertEquals("delay-boom", captured.get().getMessage());
    }
}

package com.adamk33n3r.runelite.watchdog.nodegraph;

import com.adamk33n3r.nodegraph.Connection;
import com.adamk33n3r.nodegraph.nodes.constants.Num;
import com.adamk33n3r.nodegraph.nodes.math.Add;
import com.adamk33n3r.nodegraph.nodes.math.MathNode;
import org.junit.Test;

import static org.junit.Assert.*;

public class MathNodeTest {

    // 1. Add extends MathNode
    @Test
    public void test_add_is_instance_of_math_node() {
        assertTrue(new Add() instanceof MathNode);
    }

    // 2. Default values: 0 + 0 = 0
    @Test
    public void test_add_computes_sum_from_default_values() {
        Add add = new Add();
        add.process();
        assertEquals(0.0, add.getResult().getValue().doubleValue(), 0.0001);
    }

    // 3. setValue on both inputs then process
    @Test
    public void test_add_computes_sum_after_setValue() {
        Add add = new Add();
        add.getA().setValue(3);
        add.getB().setValue(4);
        add.process();
        assertEquals(7.0, add.getResult().getValue().doubleValue(), 0.0001);
    }

    // 4. Connecting Num → Add.a must not cause a StackOverflowError
    @Test
    public void test_add_connection_does_not_stack_overflow() {
        Num num = new Num();
        num.setValue(10);
        Add add = new Add();
        new Connection<>(num.getValue(), add.getA());
    }

    // 5. Wired inputs: result updates when source values change via push
    @Test
    public void test_add_recomputes_on_input_push() {
        Num numA = new Num();
        Num numB = new Num();
        numA.setValue(5);
        numB.setValue(3);

        Add add = new Add();
        new Connection<>(numA.getValue(), add.getA());
        new Connection<>(numB.getValue(), add.getB());

        // 5 + 3 = 8
        assertEquals(8.0, add.getResult().getValue().doubleValue(), 0.0001);

        // Push a new value: 10 + 3 = 13
        numA.setValue(10);
        assertEquals(13.0, add.getResult().getValue().doubleValue(), 0.0001);
    }
}

package com.adamk33n3r.runelite.watchdog.nodegraph;

import com.adamk33n3r.nodegraph.Graph;
import com.adamk33n3r.nodegraph.nodes.utility.DisplayNode;
import com.adamk33n3r.runelite.watchdog.serialization.WatchdogGsonFactory;

import com.google.gson.Gson;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

public class DisplayNodeTest {

    private Gson gson;

    @Before
    public void setup() {
        this.gson = WatchdogGsonFactory.create(RuneLiteAPI.GSON);
    }

    @Test
    public void displayNode_rendersPrimitive_asToString() {
        DisplayNode node = new DisplayNode();
        node.getValue().setValue(42);
        assertEquals("42", node.getStringRepresentation());
    }

    @Test
    public void displayNode_rendersArray_asBracketedList() {
        DisplayNode node = new DisplayNode();
        node.getValue().setValue(new String[]{"a", "b"});
        String repr = node.getStringRepresentation();
        assertTrue(repr.startsWith("[") && repr.contains("2"));
    }

    @Test
    public void displayNode_rendersBoolean_asCheckmark() {
        DisplayNode node = new DisplayNode();
        node.getValue().setValue(true);
        assertEquals("✔", node.getStringRepresentation());

        node.getValue().setValue(false);
        assertEquals("✖", node.getStringRepresentation());
    }

    @Test
    public void displayNode_serializesAndDeserializes() {
        Graph graph = new Graph();
        graph.add(new DisplayNode());
        String json = gson.toJson(graph, Graph.class);
        Graph loaded = gson.fromJson(json, Graph.class);
        assertEquals(1, loaded.getNodes().size());
        assertTrue(loaded.getNodes().get(0) instanceof DisplayNode);
    }
}

package com.adamk33n3r.runelite.watchdog.nodegraph;

import com.adamk33n3r.nodegraph.nodes.math.Ceiling;
import com.adamk33n3r.nodegraph.nodes.math.Floor;
import com.adamk33n3r.nodegraph.nodes.math.MathNode;
import com.adamk33n3r.nodegraph.nodes.math.Round;
import org.junit.Test;

import static org.junit.Assert.*;

public class MathNodeRoundingTest {

    // --- Floor ---

    @Test
    public void floor_extends_math_node() {
        assertTrue(new Floor() instanceof MathNode);
    }

    @Test
    public void floor_default_value_is_zero() {
        Floor floor = new Floor();
        floor.process();
        assertEquals(0.0, floor.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void floor_rounds_positive_fraction_down() {
        Floor floor = new Floor();
        floor.getValue().setValue(3.9);
        floor.process();
        assertEquals(3.0, floor.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void floor_rounds_negative_fraction_down() {
        Floor floor = new Floor();
        floor.getValue().setValue(-2.1);
        floor.process();
        assertEquals(-3.0, floor.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void floor_recomputes_reactively_on_value_change() {
        Floor floor = new Floor();
        floor.getValue().setValue(1.7);
        assertEquals(1.0, floor.getResult().getValue().doubleValue(), 0.0001);

        floor.getValue().setValue(4.9);
        assertEquals(4.0, floor.getResult().getValue().doubleValue(), 0.0001);
    }

    // --- Ceiling ---

    @Test
    public void ceiling_extends_math_node() {
        assertTrue(new Ceiling() instanceof MathNode);
    }

    @Test
    public void ceiling_default_value_is_zero() {
        Ceiling ceiling = new Ceiling();
        ceiling.process();
        assertEquals(0.0, ceiling.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void ceiling_rounds_positive_fraction_up() {
        Ceiling ceiling = new Ceiling();
        ceiling.getValue().setValue(3.1);
        ceiling.process();
        assertEquals(4.0, ceiling.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void ceiling_rounds_negative_fraction_up() {
        Ceiling ceiling = new Ceiling();
        ceiling.getValue().setValue(-2.9);
        ceiling.process();
        assertEquals(-2.0, ceiling.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void ceiling_recomputes_reactively_on_value_change() {
        Ceiling ceiling = new Ceiling();
        ceiling.getValue().setValue(1.2);
        assertEquals(2.0, ceiling.getResult().getValue().doubleValue(), 0.0001);

        ceiling.getValue().setValue(5.0);
        assertEquals(5.0, ceiling.getResult().getValue().doubleValue(), 0.0001);
    }

    // --- Round ---

    @Test
    public void round_extends_math_node() {
        assertTrue(new Round() instanceof MathNode);
    }

    @Test
    public void round_default_value_is_zero() {
        Round round = new Round();
        round.process();
        assertEquals(0.0, round.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void round_rounds_up_at_half() {
        Round round = new Round();
        round.getValue().setValue(2.5);
        round.process();
        assertEquals(3.0, round.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void round_rounds_down_below_half() {
        Round round = new Round();
        round.getValue().setValue(2.4);
        round.process();
        assertEquals(2.0, round.getResult().getValue().doubleValue(), 0.0001);
    }

    @Test
    public void round_recomputes_reactively_on_value_change() {
        Round round = new Round();
        round.getValue().setValue(1.6);
        assertEquals(2.0, round.getResult().getValue().doubleValue(), 0.0001);

        round.getValue().setValue(1.4);
        assertEquals(1.0, round.getResult().getValue().doubleValue(), 0.0001);
    }
}

package com.adamk33n3r.runelite.watchdog.nodegraph;

import com.adamk33n3r.nodegraph.Graph;
import com.adamk33n3r.nodegraph.nodes.utility.NoteNode;
import com.adamk33n3r.runelite.watchdog.serialization.WatchdogGsonFactory;

import com.google.gson.Gson;
import net.runelite.http.api.RuneLiteAPI;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

public class NoteNodeTest {

    private Gson gson;

    @Before
    public void setup() {
        this.gson = WatchdogGsonFactory.create(RuneLiteAPI.GSON);
    }

    @Test
    public void noteNode_preservesText_afterRoundTrip() {
        Graph graph = new Graph();
        NoteNode note = new NoteNode();
        note.getNote().setValue("Hello World");
        graph.add(note);

        Graph loaded = roundTrip(graph);
        NoteNode loadedNote = (NoteNode) loaded.getNodes().get(0);
        assertEquals("Hello World", loadedNote.getNote().getValue());
    }

    @Test
    public void noteNode_withNoText_serializesCleanly() {
        Graph graph = new Graph();
        NoteNode note = new NoteNode();
        graph.add(note);

        Graph loaded = roundTrip(graph);
        assertEquals(1, loaded.getNodes().size());
        assertTrue(loaded.getNodes().get(0) instanceof NoteNode);
    }

    @Test
    public void graphSerializer_unknownNodeType_deserializesAsNoteNode() {
        String json = "{\"nodes\":[{\"id\":\"00000000-0000-0000-0000-000000000001\",\"x\":0,\"y\":0,\"type\":\"NotAThingNode\"}],\"connections\":[]}";
        Graph loaded = gson.fromJson(json, Graph.class);
        assertEquals(1, loaded.getNodes().size());
        assertTrue(loaded.getNodes().get(0) instanceof NoteNode);
        NoteNode note = (NoteNode) loaded.getNodes().get(0);
        assertEquals("NotAThingNode", note.getOriginalType());
    }

    @Test
    public void graphSerializer_unknownNodeType_survivesSaveAfterLoad() {
        String original = "{\"nodes\":[{\"id\":\"00000000-0000-0000-0000-000000000001\",\"x\":10,\"y\":20,\"type\":\"NotAThingNode\",\"someData\":42}],\"connections\":[]}";
        Graph loaded = gson.fromJson(original, Graph.class);
        String resaved = gson.toJson(loaded, Graph.class);
        // Re-serialize and deserialize again — node must still be a NoteNode with original type
        Graph reloaded = gson.fromJson(resaved, Graph.class);
        assertEquals(1, reloaded.getNodes().size());
        NoteNode note = (NoteNode) reloaded.getNodes().get(0);
        assertEquals("NotAThingNode", note.getOriginalType());
    }

    private Graph roundTrip(Graph graph) {
        String json = gson.toJson(graph, Graph.class);
        return gson.fromJson(json, Graph.class);
    }
}

package com.adamk33n3r.runelite.watchdog.nodegraph;

import com.adamk33n3r.runelite.watchdog.InventoryItemData;

import net.runelite.api.ItemComposition;

import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.*;

public class InventoryItemDataMapTest {

    private static InventoryItemData itemData(String name) {
        ItemComposition comp = Mockito.mock(ItemComposition.class);
        Mockito.when(comp.getName()).thenReturn(name);
        return InventoryItemData.builder().itemComposition(comp).quantity(1).build();
    }

    // ── constructors ──────────────────────────────────────────────────────────

    @Test
    public void convenience_constructor_creates_empty_slots_array() {
        var map = new InventoryItemData.InventoryItemDataMap(3);
        assertNotNull(map.getSlots());
        assertEquals(0, map.getSlots().length);
        assertEquals(3, map.getItemCount());
    }

    @Test
    public void full_constructor_preserves_slots_array() {
        InventoryItemData[] slots = new InventoryItemData[4];
        slots[0] = itemData("Shark");
        slots[2] = itemData("Cake");

        var map = new InventoryItemData.InventoryItemDataMap(2, slots);

        assertSame(slots, map.getSlots());
        assertEquals("Shark", map.getSlots()[0].getItemComposition().getName());
        assertNull(map.getSlots()[1]);
        assertEquals("Cake", map.getSlots()[2].getItemComposition().getName());
    }

    // ── copy constructor ──────────────────────────────────────────────────────

    @Test
    public void copy_constructor_clones_slots_array_not_alias() {
        InventoryItemData[] slots = new InventoryItemData[2];
        slots[0] = itemData("Shark");
        var original = new InventoryItemData.InventoryItemDataMap(1, slots);

        var copy = new InventoryItemData.InventoryItemDataMap(original);

        assertNotSame(original.getSlots(), copy.getSlots());
        assertEquals(original.getSlots().length, copy.getSlots().length);
        assertSame(original.getSlots()[0], copy.getSlots()[0]);
    }

    @Test
    public void copy_constructor_does_not_carry_over_mutation() {
        InventoryItemData[] slots = new InventoryItemData[2];
        slots[0] = itemData("Shark");
        var original = new InventoryItemData.InventoryItemDataMap(1, slots);
        var copy = new InventoryItemData.InventoryItemDataMap(original);

        // Mutating the copy's array should not affect the original
        copy.getSlots()[0] = itemData("Cake");

        assertEquals("Shark", original.getSlots()[0].getItemComposition().getName());
    }

    @Test
    public void copy_constructor_preserves_items_map() {
        InventoryItemData item = itemData("Coins");
        var original = new InventoryItemData.InventoryItemDataMap(1, new InventoryItemData[0]);
        original.getItems().put(995, item);

        var copy = new InventoryItemData.InventoryItemDataMap(original);

        assertTrue(copy.getItems().containsKey(995));
        assertSame(item, copy.getItems().get(995));
    }
}

package com.adamk33n3r.runelite.watchdog.nodegraph;

