package com.adamk33n3r.nodegraph;

import com.adamk33n3r.nodegraph.nodes.utility.NoteNode;

import com.google.gson.*;
import lombok.extern.slf4j.Slf4j;

import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

@Slf4j
public class GraphSerializer implements JsonSerializer<Graph>, JsonDeserializer<Graph> {
    private final Gson subGson;
    private final NodeTypeRegistry nodeRegistry;

    public GraphSerializer(Gson gson, NodeTypeRegistry nodeRegistry) {
        this.subGson = gson;
        this.nodeRegistry = nodeRegistry;
    }

    @Override
    public JsonElement serialize(Graph graph, Type type, JsonSerializationContext ctx) {
        JsonObject root = new JsonObject();

        JsonArray nodesArr = new JsonArray();
        for (Node node : graph.getNodes()) {
            JsonObject nodeObj = new JsonObject();
            nodeObj.addProperty("id", node.getId().toString());
            nodeObj.addProperty("x", node.getX());
            nodeObj.addProperty("y", node.getY());
            nodeObj.addProperty("collapsed", node.isCollapsed());

            // Lossless resave for unknown-type placeholders
            if (node instanceof NoteNode) {
                NoteNode noteNode = (NoteNode) node;
                if (noteNode.getOriginalType() != null && noteNode.getOriginalJson() != null) {
                    for (Map.Entry<String, JsonElement> entry : noteNode.getOriginalJson().entrySet()) {
                        nodeObj.add(entry.getKey(), entry.getValue());
                    }
                    nodesArr.add(nodeObj);
                    continue;
                }
            }

            if (!this.nodeRegistry.serialize(node, nodeObj, this.subGson)) continue;
            nodesArr.add(nodeObj);
        }
        root.add("nodes", nodesArr);

        JsonArray connectionsArr = new JsonArray();
        for (Connection<?> conn : graph.getConnections()) {
            JsonObject connObj = new JsonObject();
            connObj.addProperty("fromNode", conn.getOutput().getNode().getId().toString());
            connObj.addProperty("fromVar", conn.getOutput().getName());
            connObj.addProperty("toNode", conn.getInput().getNode().getId().toString());
            connObj.addProperty("toVar", conn.getInput().getName());
            connectionsArr.add(connObj);
        }
        root.add("connections", connectionsArr);

        return root;
    }

    @Override
    public Graph deserialize(JsonElement json, Type type, JsonDeserializationContext ctx) throws JsonParseException {
        JsonObject root = json.getAsJsonObject();
        Graph graph = new Graph();
        Map<String, Node> nodeById = new HashMap<>();

        JsonArray nodesArr = root.getAsJsonArray("nodes");
        if (nodesArr != null) {
            for (JsonElement nodeElem : nodesArr) {
                JsonObject nodeObj = nodeElem.getAsJsonObject();
                String id = nodeObj.has("id") ? nodeObj.get("id").getAsString() : null;
                int x = nodeObj.has("x") ? nodeObj.get("x").getAsInt() : 0;
                int y = nodeObj.has("y") ? nodeObj.get("y").getAsInt() : 0;
                boolean collapsed = nodeObj.has("collapsed") && nodeObj.get("collapsed").getAsBoolean();

                Node node;
                try {
                    node = this.nodeRegistry.deserialize(nodeObj, this.subGson);
                    if (node == null) {
                        String nodeType = nodeObj.has("type") ? nodeObj.get("type").getAsString() : "unknown";
                        log.warn("Unknown node type during deserialization, creating placeholder: {}", nodeType);
                        NoteNode placeholder = new NoteNode();
                        placeholder.setOriginalType(nodeType);
                        placeholder.setOriginalJson(nodeObj.deepCopy());
                        node = placeholder;
                    }
                } catch (Exception e) {
                    String nodeType = nodeObj.has("type") ? nodeObj.get("type").getAsString() : "unknown";
                    log.warn("Failed to deserialize node of type {}: {}", nodeType, e.getMessage());
                    continue;
                }

                node.setX(x);
                node.setY(y);
                node.setCollapsed(collapsed);
                if (id != null) {
                    node.setId(UUID.fromString(id));
                    nodeById.put(id, node);
                }
                graph.add(node);
            }
        }

        JsonArray connectionsArr = root.getAsJsonArray("connections");
        if (connectionsArr != null) {
            for (JsonElement connElem : connectionsArr) {
                JsonObject connObj = connElem.getAsJsonObject();
                String fromNodeId = connObj.get("fromNode").getAsString();
                String fromVar = connObj.get("fromVar").getAsString();
                String toNodeId = connObj.get("toNode").getAsString();
                String toVar = connObj.get("toVar").getAsString();

                Node fromNode = nodeById.get(fromNodeId);
                Node toNode = nodeById.get(toNodeId);
                if (fromNode == null || toNode == null) {
                    log.warn("Could not find nodes for connection: {} -> {}", fromNodeId, toNodeId);
                    continue;
                }

                VarOutput<?> output = fromNode.getOutputs().get(fromVar);
                VarInput<?> input = toNode.getInputs().get(toVar);
                if (output == null || input == null) {
                    log.warn("Could not find vars for connection: {}.{} -> {}.{}", fromNodeId, fromVar, toNodeId, toVar);
                    continue;
                }

                this.connectUnchecked(graph, output, input);
            }
        }

        return graph;
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    private void connectUnchecked(Graph graph, VarOutput<?> output, VarInput<?> input) {
        graph.connect((VarOutput) output, (VarInput) input);
    }
}

package com.adamk33n3r.nodegraph;

import com.adamk33n3r.nodegraph.nodes.ActionNode;
import com.adamk33n3r.nodegraph.nodes.flow.Counter;
import com.adamk33n3r.nodegraph.nodes.flow.DelayNode;
import com.adamk33n3r.nodegraph.nodes.flow.TimerNode;
import com.adamk33n3r.nodegraph.nodes.TriggerNode;
import com.adamk33n3r.nodegraph.nodes.flow.Branch;
import com.adamk33n3r.runelite.watchdog.alerts.Alert;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import java.util.AbstractMap;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;
import java.util.stream.Collectors;
import java.util.stream.Stream;

@Slf4j
public class Graph {
    @Getter
    private final List<Node> nodes = new ArrayList<>();
    @Getter
    private final List<Connection<?>> connections = new ArrayList<>();

    @Setter
    private Consumer<Throwable> onError;

    // Lazy-initialized, daemon-threaded scheduler — shared across all async nodes in this graph.
    private ScheduledExecutorService scheduler;

    private ScheduledExecutorService getScheduler() {
        if (this.scheduler == null) {
            this.scheduler = Executors.newScheduledThreadPool(1, r -> {
                Thread t = new Thread(r, "nodegraph-timer");
                t.setDaemon(true);
                return t;
            });
        }
        return this.scheduler;
    }

    private Runnable wrap(Runnable r) {
        return () -> {
            try {
                r.run();
            } catch (Throwable e) {
                log.error("Exception in timer exec chain", e);
                if (this.onError != null) this.onError.accept(e);
            }
        };
    }

    public void shutdown() {
        if (this.scheduler != null) {
            this.scheduler.shutdown();
            this.scheduler = null;
        }
    }

    public void add(Node node) {
        this.nodes.add(node);
    }

    public void remove(Node node) {
        this.nodes.remove(node);
        List<Connection<?>> toRemove = this.connections.stream()
            .filter(c -> c.getOutput().getNode().equals(node) || c.getInput().getNode().equals(node))
            .collect(Collectors.toList());
        toRemove.forEach(Connection::remove);
        this.connections.removeAll(toRemove);
    }

    private boolean wouldCreateCycle(VarOutput<?> output, VarInput<?> input) {
        if (input.isTerminatesExec()) return false;

        Node source = output.getNode();
        Node dest = input.getNode();
        Set<Node> visited = new HashSet<>();
        Deque<Node> stack = new ArrayDeque<>();
        stack.push(source);
        while (!stack.isEmpty()) {
            Node node = stack.pop();
            if (node == dest) return true;
            if (!visited.add(node)) continue;
            this.connections.stream()
                .filter(c -> c.getInput().getNode() == node)
                .filter(c -> !c.getInput().isTerminatesExec())
                .map(c -> c.getOutput().getNode())
                .forEach(stack::push);
        }
        return false;
    }

    public <T> boolean connect(VarOutput<T> output, VarInput<T> input) {
        if (output.getConnections().stream().anyMatch(c -> c.getInput().equals(input))) {
            log.warn("Connection already exists");
            return false;
        }

        if (wouldCreateCycle(output, input)) {
            log.warn("Connection would create a cycle");
            return false;
        }

        // There is an existing connection to this input, disconnect it (unless multi-connection is allowed)
        if (!input.isAllowMultipleConnections() && input.getConnection() != null) {
            this.disconnect(input.getConnection().getOutput(), input);
        }

        Connection<?> connection = new Connection<>(output, input);
        this.connections.add(connection);
        return true;
    }

    public void disconnect(VarOutput<?> output, VarInput<?> input) {
        this.connections.stream()
            .filter(c -> c.getOutput().equals(output) && c.getInput().equals(input))
            .findFirst()
            .ifPresent(c -> {
                c.remove();
                this.connections.remove(c);
            });
    }

    public <T extends Node> Stream<T> getNodesOfType(Class<T> nodeClass) {
        return nodes.stream().filter(nodeClass::isInstance).map(nodeClass::cast);
    }

    public Stream<TriggerNode> getTriggerNodes() {
        return this.nodes.stream()
            .filter(n -> n instanceof TriggerNode)
            .map(n -> (TriggerNode) n);
    }

    /**
     * Returns all TriggerNodes whose embedded alert is an instance of the given alert class.
     */
    public <T extends Alert> Stream<TriggerNode> getTriggerNodesOfType(Class<T> alertClass) {
        return nodes.stream()
            .filter(n -> n instanceof TriggerNode)
            .map(n -> (TriggerNode) n)
            .filter(tn -> alertClass.isInstance(tn.getAlert()));
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        for (Node node : this.nodes) {
            if (!(node instanceof TriggerNode)) {
                continue;
            }
            sb.append(node.getClass().getSimpleName()).append(":\n");
            List<Connection<?>> connections = this.connections.stream()
                .filter(connection -> connection.getOutput().getNode() == node)
                .collect(Collectors.toList());
            if (connections.isEmpty()) {
                sb.append("  No connections\n");
            } else {
                connections.forEach(connection -> {
                    sb.append("  ")
                        .append(connection.getOutput().getNode().getClass().getSimpleName())
                        .append(":")
                        .append(connection.getOutput().getName())
                        .append(" -> ")
                        .append(connection.getInput().getName())
                        .append(":")
                        .append(connection.getInput().getNode().getClass().getSimpleName())
                        .append("\n");
                });
            }
        }
        return sb.toString();
    }

    public void process(Node node) {
        node.process();
        this.connections.stream()
            .filter(c -> c.getOutput().getNode() == node)
            .filter(c -> !c.getInput().isTerminatesExec())
            .map(c -> c.getInput().getNode())
            .distinct()
            .forEach(this::process);
    }

    /**
     * Finds and returns all notifications recursively reachable from triggerNode
     * via exec connections, including those behind ActionNodes and DelayNodes.
     */
    public List<ActionNode> getReachableActionsFromTrigger(TriggerNode triggerNode) {
        List<ActionNode> reachableNotifications = new ArrayList<>();
        List<Node> nodesToProcess = new ArrayList<>();
        nodesToProcess.add(triggerNode);
        while (!nodesToProcess.isEmpty()) {
            Node node = nodesToProcess.remove(0);
            if (node instanceof TriggerNode && !((TriggerNode) node).getEnabled().getValue()) {
                continue;
            }
            if (node instanceof ActionNode) {
                ActionNode action = (ActionNode) node;
                if (action.getEnabled().getValue()) {
                    reachableNotifications.add(action);
                }
                // Fall through to also follow this node's exec output
            }
            nodesToProcess.addAll(this.getExecDownstream(node));
        }
        return reachableNotifications;
    }

    /**
     * Traverses the exec chain starting from startNode, firing enabled ActionNodes
     * immediately and spawning daemon threads to handle DelayNodes.
     *
     * The BFS queue carries (node, arrivingInput) pairs so that stateful nodes like
     * Counter can distinguish which of their exec inputs was triggered.
     * arrivingInput is null only for the startNode entry.
     */
    public void executeExecChain(Node startNode, String[] captureGroups) {
        List<Map.Entry<Node, VarInput<ExecSignal>>> nodesToProcess = new ArrayList<>();
        nodesToProcess.add(new AbstractMap.SimpleEntry<>(startNode, null));
        this.executeExecChainBFS(nodesToProcess, captureGroups);
    }

    @SuppressWarnings("unchecked")
    private void executeExecChainBFS(List<Map.Entry<Node, VarInput<ExecSignal>>> nodesToProcess, String[] captureGroups) {
        while (!nodesToProcess.isEmpty()) {
            Map.Entry<Node, VarInput<ExecSignal>> entry = nodesToProcess.remove(0);
            Node node = entry.getKey();
            VarInput<ExecSignal> arrivingInput = entry.getValue();

            if (node instanceof TriggerNode && !((TriggerNode) node).getEnabled().getValue()) {
                continue;
            }

            if (node instanceof Counter) {
                Counter counter = (Counter) node;
                if (arrivingInput == counter.getReset()) {
                    counter.reset();
                    continue;  // reset is terminal — no exec output
                } else {
                    counter.increment();
                    // fall through to add exec-downstream
                }
            }

            if (node instanceof TimerNode) {
                TimerNode timer = (TimerNode) node;
                if (arrivingInput == timer.getReset()) {
                    timer.cancelCurrentFuture();
                    continue; // reset is terminal — no exec output
                }
                // Exec arrival — cancel any running future (restart semantics) then schedule
                timer.cancelCurrentFuture();
                timer.getCanceled().set(false);
                int durationMs = timer.getDurationMs().getValue().intValue();
                boolean pulse = Boolean.TRUE.equals(timer.getPulse().getValue());
                if (durationMs <= 0) {
                    // degenerate: fire execOut immediately as a pass-through
                    this.executeFromOutput(timer.getExecOut(), captureGroups);
                    continue;
                }
                ScheduledExecutorService sched = this.getScheduler();
                Runnable fireExec = this.wrap(() -> this.executeFromOutput(timer.getExecOut(), captureGroups));
                Runnable firePulse = this.wrap(() -> this.executeFromOutput(timer.getPulseOut(), captureGroups));
                if (!pulse) {
                    timer.setCurrentFuture(sched.schedule(fireExec, durationMs, TimeUnit.MILLISECONDS));
                } else {
                    timer.setCurrentFuture(sched.schedule(this.wrap(() -> {
                        fireExec.run();
                        // Guard against Reset arriving between fireExec and scheduleAtFixedRate.
                        if (!timer.getCanceled().get()) {
                            timer.setCurrentFuture(sched.scheduleAtFixedRate(firePulse, durationMs, durationMs, TimeUnit.MILLISECONDS));
                        }
                    }), durationMs, TimeUnit.MILLISECONDS));
                }
                continue;
            }

            if (node instanceof ActionNode) {
                ActionNode action = (ActionNode) node;
                if (action.getEnabled().getValue()) {
                    try {
                        action.fire(captureGroups);
                    } catch (Throwable e) {
                        log.error("Exception in ActionNode execution", e);
                        if (this.onError != null) this.onError.accept(e);
                    }
                }
                // Fall through to follow exec downstream from this action
            }

            if (node instanceof Branch) {
                Branch branch = (Branch) node;
                boolean cond = branch.getCondition().getValue();
                VarOutput<ExecSignal> activeOut = cond ? branch.getExecTrue() : branch.getExecFalse();
                this.connections.stream()
                    .filter(c -> c.getOutput() == activeOut)
                    .map(c -> (Map.Entry<Node, VarInput<ExecSignal>>) new AbstractMap.SimpleEntry<>(
                        c.getInput().getNode(), (VarInput<ExecSignal>) c.getInput()))
                    .forEach(nodesToProcess::add);
                continue;
            }

            if (node instanceof DelayNode) {
                int delayMs = ((DelayNode) node).getDelayMs().getValue().intValue();
                if (delayMs > 0) {
                    List<Map.Entry<Node, VarInput<ExecSignal>>> downstream = this.getExecEntriesDownstream(node);
                    this.getScheduler().schedule(
                        this.wrap(() -> this.executeExecChainBFS(downstream, captureGroups)),
                        delayMs,
                        TimeUnit.MILLISECONDS
                    );
                    continue; // Don't add downstream to the immediate BFS queue
                }
                // delayMs == 0: fall through and add downstream immediately
            }

            nodesToProcess.addAll(this.getExecEntriesDownstream(node));
        }
    }

    private List<Node> getExecDownstream(Node node) {
        return this.connections.stream()
            .filter(c -> c.getOutput().getNode() == node && c.getOutput().getType() == ExecSignal.class)
            .map(c -> c.getInput().getNode())
            .distinct()
            .collect(Collectors.toList());
    }

    @SuppressWarnings("unchecked")
    private List<Map.Entry<Node, VarInput<ExecSignal>>> getExecEntriesDownstream(Node node) {
        return this.connections.stream()
            .filter(c -> c.getOutput().getNode() == node && c.getOutput().getType() == ExecSignal.class)
            .map(c -> (Map.Entry<Node, VarInput<ExecSignal>>) new AbstractMap.SimpleEntry<>(
                c.getInput().getNode(), (VarInput<ExecSignal>) c.getInput()))
            .collect(Collectors.toList());
    }

    // Routes execution through a specific exec output pin — used by TimerNode which has two exec outputs.
    @SuppressWarnings("unchecked")
    private void executeFromOutput(VarOutput<ExecSignal> output, String[] captureGroups) {
        List<Map.Entry<Node, VarInput<ExecSignal>>> entries = this.connections.stream()
            .filter(c -> c.getOutput() == output)
            .map(c -> (Map.Entry<Node, VarInput<ExecSignal>>) new AbstractMap.SimpleEntry<>(
                c.getInput().getNode(), (VarInput<ExecSignal>) c.getInput()))
            .collect(Collectors.toList());
        this.executeExecChainBFS(entries, captureGroups);
    }
}

package com.adamk33n3r.nodegraph;

import lombok.Getter;

@Getter
public class Connection<T> {
    private final VarOutput<T> output;
    private final VarInput<T> input;

    public Connection(VarOutput<T> output, VarInput<T> input) {
        this.output = output;
        this.input = input;
        this.output.addConnection(this);
        this.input.addConnection(this);
        this.input.setValue(this.output.getValue());
    }

    public void send(T value) {
        this.input.setValue(value);
    }

    public T get() {
        return this.output.getValue();
    }

    public void remove() {
        this.output.removeConnection(this);
        this.input.removeConnection(this);
    }
}

package com.adamk33n3r.nodegraph;

import lombok.Getter;

@Getter
public final class ExecSignal {
    private final String[] captureGroups;

    public ExecSignal(String[] captureGroups) {
        this.captureGroups = captureGroups != null ? captureGroups : new String[0];
    }

    @Override
    public String toString() {
        if (captureGroups.length == 0) return "[ ]";
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < captureGroups.length; i++) {
            if (i > 0) sb.append(", ");
            sb.append('"').append(captureGroups[i]).append('"');
        }
        return sb.append(']').toString();
    }
}

package com.adamk33n3r.nodegraph.nodes.utility;

import com.adamk33n3r.nodegraph.VarInput;
import com.adamk33n3r.nodegraph.nodes.NoProcessNode;
import com.adamk33n3r.runelite.watchdog.InventoryItemData;
import lombok.Getter;

@Getter
public class DisplayNode extends NoProcessNode {
    private final VarInput<Object> value = new VarInput<>(this, "Value", Object.class, "");

    public DisplayNode() {
        reg(this.value);
    }

    /** Returns the human-readable string for the current value. */
    public String getStringRepresentation() {
        Object v = this.value.getValue();
        if (v == null) return "null";
        if (v.getClass().isArray()) {
            int length = ((Object[]) v).length;
            return "[" + v.getClass().getComponentType().getSimpleName() + "...][" + length + "]";
        } else if (v instanceof InventoryItemData.InventoryItemDataMap) {
            InventoryItemData.InventoryItemDataMap invMap = (InventoryItemData.InventoryItemDataMap) v;
            int i = 0;
            StringBuilder sb = new StringBuilder();
            for (var item : invMap.getItems().entrySet()) {
                sb.append(item.getValue().getItemComposition().getName())
                  .append("(").append(item.getValue().getQuantity()).append("),");
                if (++i > 3) break;
            }
            if (invMap.getItems().size() > 3) sb.append("...");
            else if (!invMap.getItems().isEmpty()) sb.deleteCharAt(sb.length() - 1);
            return sb.toString();
        } else if (v instanceof Boolean) {
            return (Boolean) v ? "✔" : "✖";
        } else {
            return v.toString();
        }
    }
}

