        super(alert, onChange);
        this.client = client;
        this.init();
    }

    @Override
    public void buildTypeContent() {
        JPanel pointPanel = new JPanel(new GridLayout(1, 3, 5, 5));
        JPanel xPos = PanelUtils.createLabeledComponent(
            "X Pos", "The X position",
            PanelUtils.createSpinner(this.alert.getWorldPoint().getX(), Integer.MIN_VALUE, Integer.MAX_VALUE, 1,
