package com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections;

import com.adamk33n3r.runelite.watchdog.InventoryItemData.InventoryItemDataMap;
import net.runelite.api.coords.WorldPoint;

import java.awt.Color;
import java.util.LinkedHashMap;
import java.util.Map;

public final class TypeColorRegistry {
    public static final Color DEFAULT_COLOR = new Color(255, 0, 255); // bright magenta — unmapped type
    public static final Color EXEC_COLOR = new Color(220, 220, 220);
    public static final Color DISCONNECTED_COLOR = new Color(75, 75, 75);

    private static final Map<Class<?>, Color> COLORS = new LinkedHashMap<>();

    static {
        COLORS.put(Number.class,     new Color(0,   180, 200)); // muted cyan
        COLORS.put(Boolean.class,    new Color(60,  180, 60));  // muted green
        COLORS.put(WorldPoint.class, new Color(200, 175, 0));   // muted yellow/gold
        COLORS.put(String.class,     new Color(210, 120, 30));  // muted orange
        COLORS.put(InventoryItemDataMap.class, new Color(0, 102, 204)); // my fave blue
        COLORS.put(Enum.class,       new Color(0, 0, 0, 0)); // transparent since unsupported right now
        COLORS.put(Object.class,     new Color(150, 150, 150)); // grey
//        COLORS.put()
    }

    public static Color getColor(Class<?> type) {
        Color c = COLORS.get(type);
        if (c != null) return c;
        // Walk registered supertypes — handles Integer/Double → Number, etc.
        // Skip Object.class here so it only matches via exact lookup above.
        for (Map.Entry<Class<?>, Color> entry : COLORS.entrySet()) {
            if (entry.getKey() != Object.class && entry.getKey().isAssignableFrom(type)) return entry.getValue();
        }
        return DEFAULT_COLOR;
    }

    private TypeColorRegistry() {}
}

package com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections;


import javax.swing.JComponent;
import java.awt.*;
import java.awt.geom.CubicCurve2D;

import static com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.TypeColorRegistry.EXEC_COLOR;

public class Connection extends JComponent {
    protected static final int END_SIZE = 10;
    protected static final int BOUNDS_OFFSET = 40;

    protected Point start;
    protected Point end;
    protected boolean exec = false;
    protected Color lineColor = TypeColorRegistry.DEFAULT_COLOR;

    public Connection(Point start, Point end) {
        this.start = start;
        this.end = end;
        this.recalculateBounds();
    }

    public void setExec(boolean exec) {
        this.exec = exec;
    }

    public void setLineColor(Color lineColor) {
        this.lineColor = lineColor;
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);

        int startX = this.start.x;
        startX += 10;
        int startY = this.start.y;
        int endX = this.end.x;
        endX -= 2;
        int endY = this.end.y;

        Graphics2D g2 = (Graphics2D) g;
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        g.translate(BOUNDS_OFFSET, BOUNDS_OFFSET);

        Color drawColor = this.exec ? EXEC_COLOR : this.lineColor;
        int lineWidth = this.exec ? 5 : 4;

        CubicCurve2D.Double curve = new CubicCurve2D.Double(
            // +2 to offset to be on the edge
            startX+2, startY,
            startX + 100, startY,
            endX - 100, endY,
            endX-10, endY);

        // Black border pass — drawn 2px wider underneath
        g2.setColor(Color.BLACK);
        g2.setStroke(new BasicStroke(lineWidth + 2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g2.draw(curve);

        // Colored fill pass on top
        g2.setColor(drawColor);
        g2.setStroke(new BasicStroke(lineWidth, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g2.draw(curve);

        // Start cap — black border then colored fill
        int arcDiameter = 20;
        g2.setColor(Color.BLACK);
        g2.setStroke(new BasicStroke(5, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        g2.fillArc(startX - (arcDiameter + 4) / 2, startY - (arcDiameter + 4) / 2, arcDiameter + 4, arcDiameter + 4, 90, -180);
        g2.setColor(drawColor);
        g2.fillArc(startX - arcDiameter / 2, startY - arcDiameter / 2, arcDiameter, arcDiameter, 90, -180);

        // Arrowhead — black inflated polygon first, then colored polygon on top
        int[] arrowXs = new int[]{endX - 10, endX - 10, endX};
        int[] arrowYs = new int[]{endY - 10, endY + 10, endY};
        int[] arrowXsBorder = new int[]{endX - 12, endX - 12, endX + 3};
        int[] arrowYsBorder = new int[]{endY - 14, endY + 14, endY};
        g2.setColor(Color.BLACK);
        g2.fillPolygon(arrowXsBorder, arrowYsBorder, 3);
        g2.setColor(drawColor);
        g2.fillPolygon(arrowXs, arrowYs, 3);

        g.translate(-BOUNDS_OFFSET, -BOUNDS_OFFSET);
    }

    public void recalculateBounds() {
        this.setBounds(
            Math.min(this.start.x, this.end.x) - BOUNDS_OFFSET,
            Math.min(this.start.y, this.end.y) - BOUNDS_OFFSET,
            Math.abs(this.start.x - this.end.x) + BOUNDS_OFFSET * 2,
            Math.abs(this.start.y - this.end.y) + BOUNDS_OFFSET * 2
        );
    }
}

package com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections;

import com.adamk33n3r.runelite.watchdog.ui.nodegraph.NodePanel;
import lombok.Getter;

import javax.swing.JComponent;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;

import static com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.TypeColorRegistry.DISCONNECTED_COLOR;
import static com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.TypeColorRegistry.EXEC_COLOR;

@Getter
public abstract class ConnectionPoint extends JComponent {
    private final NodePanel nodePanel;
    private final boolean exec;
    /** true = right-pointing (output), false = left-pointing (input) */
    private final boolean arrowRight;
    private final Class<?> type;
    private boolean connected = false;
    protected boolean hovered = false;
    private final Dimension size = new Dimension(20, 20);

    public ConnectionPoint(NodePanel nodePanel, boolean exec, boolean arrowRight, Class<?> type) {
        this.nodePanel = nodePanel;
        this.exec = exec;
        this.arrowRight = arrowRight;
        this.type = type;
        this.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                hovered = true;
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hovered = false;
                repaint();
            }
        });
    }

    protected boolean shouldFill() {
        return false;
    }

    public void setConnected(boolean connected) {
        this.connected = connected;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g) {
        super.paintComponent(g);

        Graphics2D g2 = (Graphics2D) g;
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        if (this.exec) {
            int w = this.size.width;
            int h = this.size.height;
            int mid = h / 2;
            int[] xs, ys;
            if (this.arrowRight) {
                xs = new int[]{0, w, 0};
                ys = new int[]{0, mid, h};
            } else {
                xs = new int[]{w, 0, w};
                ys = new int[]{0, mid, h};
            }
            g2.setColor(this.connected || shouldFill() ? EXEC_COLOR : DISCONNECTED_COLOR);
            g2.fillPolygon(xs, ys, 3);
            g2.setColor(Color.BLACK);
            g2.setStroke(new BasicStroke(1f));
            g2.drawPolygon(xs, ys, 3);
        } else {
            Color typeColor = TypeColorRegistry.getColor(this.type);
            int margin = 3;
            int d = this.size.width - margin * 2;
            if (this.connected || shouldFill()) {
                g2.setColor(typeColor);
                g2.fillOval(margin, margin, d, d);
                g2.setColor(new Color(30, 30, 30));
                g2.setStroke(new BasicStroke(1f));
                g2.drawOval(margin, margin, d, d);
            } else {
                g2.setColor(typeColor);
                g2.setStroke(new BasicStroke(2f));
                g2.drawOval(margin, margin, d, d);
            }
        }
    }

    @Override
    public Dimension getPreferredSize() {
        return this.size;
    }
}

package com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections;

import com.adamk33n3r.nodegraph.ExecSignal;
