                    triggerNode.setY(py);
                    this.graph.add(triggerNode);
                    NodePanel nodePanel = this.createNodePanel(triggerNode, triggerNode.getAlert().getType().getName());
                    this.add(nodePanel, NODE_LAYER, 0);
