import javax.annotation.Nonnull;
import javax.swing.*;
import java.awt.*;
import java.util.Arrays;
import java.util.Map;
import java.util.function.BooleanSupplier;
import java.util.function.Predicate;
import java.util.function.Supplier;
import java.util.stream.Stream;

public class CustomList extends JList<Object> {
    public CustomList(Items[] items) {
        super();
        Stream<Object> objectStream = Arrays.stream(items)
            .filter(i -> i.items.length > 0)
            .flatMap(i -> Stream.concat(Stream.of("c:"+i.category), Arrays.stream(i.items)));
        this.setListData(objectStream.toArray());
        this.setCellRenderer(new DefaultListCellRenderer() {
            @Override
            public Component getListCellRendererComponent(JList list, Object value, int index, boolean isSelected, boolean cellHasFocus) {
                super.getListCellRendererComponent(list, value, index, isSelected, cellHasFocus);
                String str = value instanceof String ? (String) value : (value instanceof Displayable ? ((Displayable) value).getName() : "UNKNOWN");
                if (str.startsWith("c:")) {
                    this.setForeground(Color.LIGHT_GRAY);
                    this.setText(str.substring(2));
                    this.setEnabled(false);
//                    this.setFocusable(false);
//                    this.setOpaque(false);
                } else {
                    this.setText(str);
                }

                return this;
            }
        });

        this.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);

        this.setSelectionModel(new DefaultListSelectionModel() {
            @Override
            public void setSelectionInterval(int index0, int index1) {
                if (!CustomList.this.getModel().getElementAt(index0).toString().startsWith("c:")) {
                    super.setSelectionInterval(index0, index1);
                }
            }
        });
    }

    @Override
    public void setListData(Object[] listData) {
        this.setModel(new AbstractListModel<Object>() {
            public int getSize() { return listData.length; }
            public Object getElementAt(int i) { return listData[i]; }
        });
    }

    @Override
    public void setSelectionMode(int selectionMode) {
        super.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
    }

    @Getter
    public static class Items {
        private final Enum<?>[] items;
        private final String category;
        public Items(@Nonnull Class<? extends Enum<?>> enumClass, @Nonnull String category, @Nonnull Predicate<Enum<?>> filter) {
            this.items = Arrays.stream(enumClass.getEnumConstants())
                .filter(filter)
                .toArray(Enum<?>[]::new);
            this.category = category;
        }
    }
}

package com.adamk33n3r.runelite.watchdog.ui.nodegraph;


import lombok.RequiredArgsConstructor;

import javax.swing.*;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.BiConsumer;

@RequiredArgsConstructor
public class DraggingMouseAdapter extends MouseAdapter {
    private final BiConsumer<Point, Point> onDrag;
    private Point onDragStartPoint;

    @Override
    public void mousePressed(MouseEvent e) {
        if (SwingUtilities.isLeftMouseButton(e) && this.onDragStartPoint == null) {
            this.onDragStartPoint = e.getPoint();
        }
    }

    @Override
    public void mouseReleased(MouseEvent e) {
        this.onDragStartPoint = null;
    }

    @Override
    public void mouseDragged(MouseEvent e) {
        if (SwingUtilities.isLeftMouseButton(e) && this.onDragStartPoint != null) {
            this.onDrag.accept(this.onDragStartPoint, e.getPoint());
        }
    }
}

