import java.util.Arrays;

@Getter
public class InventoryCheckNodePanel extends NodePanel {
    private final ConnectionPointIn<InventoryItemData.InventoryItemDataMap> inventoryIn;
    private final ConnectionPointOut<Boolean> valueOut;
    private final InventoryCheck inventoryCheck;
    private final ViewInput<Boolean> matchView;
    // Index after which conditional controls are inserted (alertType row is at index 1)
    private int conditionalStartIndex;

    public InventoryCheckNodePanel(GraphPanel graphPanel, InventoryCheck node, int x, int y, String name, Color color) {
        super(graphPanel, node, x, y, name, color);
        this.inventoryCheck = node;

        // Inventory input row
        this.inventoryIn = new ConnectionPointIn<>(this, node.getInventory());
        ViewInput<InventoryItemData.InventoryItemDataMap> invView = new ViewInput<>("Inventory", node.getInventory().getValue());
        this.items.add(new ConnectionLine<>(this.inventoryIn, invView, null));

        // Alert Type — filtered to exclude ITEM_CHANGE (matches original UI)
        InventoryAlert.InventoryAlertType[] visibleTypes = Arrays.stream(InventoryAlert.InventoryAlertType.values())
            .filter(t -> t != InventoryAlert.InventoryAlertType.ITEM_CHANGE)
            .toArray(InventoryAlert.InventoryAlertType[]::new);
        ConnectionPointIn<InventoryAlert.InventoryAlertType> typeIn = new ConnectionPointIn<>(this, node.getInventoryAlertType());
        this.items.add(new ConnectionLine<>(typeIn, new EnumInput<>("Alert Type", node.getInventoryAlertType(), visibleTypes), null));

        // Record where conditional controls begin
        this.conditionalStartIndex = this.items.getComponentCount();
        this.addConditionalControls(node);

        // Result output row
        this.valueOut = new ConnectionPointOut<>(this, node.getResultOut());
        this.matchView = new ViewInput<>("Match", node.getResultOut().getValue());
        addDisposer(node.getInventory().onChange(v -> this.matchView.setValue(node.getResultOut().getValue())));
        this.items.add(new ConnectionLine<>(null, this.matchView, this.valueOut));

        // Rebuild conditional controls when alert type changes
        // Panel is constructed after graph load, so deserialization onChange has already fired.
        addDisposer(node.getInventoryAlertType().onChange(v -> {
            this.updateResult();
            SwingUtilities.invokeLater(this::rebuildContent);
        }));

        this.watchDirty(
            node.getInventoryAlertType(),
            node.getInventoryMatchType(),
            node.getItemName(),
            node.getRegexEnabled(),
            node.getItemQuantity(),
            node.getQuantityComparator()
        );

        this.pack();
    }

    private void addConditionalControls(InventoryCheck node) {
        InventoryAlert.InventoryAlertType alertType = node.getInventoryAlertType().getValue();

        if (alertType == InventoryAlert.InventoryAlertType.ITEM
            || alertType == InventoryAlert.InventoryAlertType.ITEM_CHANGE) {

            ConnectionPointIn<String> nameIn = new ConnectionPointIn<>(this, node.getItemName());
            this.items.add(new ConnectionLine<>(nameIn,
                new TextInput("Enter item name...", "Item name, supports glob (*)", node.getItemName()), null));
            addDisposer(node.getItemName().onChange(_v -> this.updateResult()));

            ConnectionPointIn<InventoryAlert.InventoryMatchType> matchIn = new ConnectionPointIn<>(this, node.getInventoryMatchType());
            this.items.add(new ConnectionLine<>(matchIn,
                new EnumInput<>("Match Type", node.getInventoryMatchType()), null));
            addDisposer(node.getInventoryMatchType().onChange(_v -> this.updateResult()));

            ConnectionPointIn<Boolean> regexIn = new ConnectionPointIn<>(this, node.getRegexEnabled());
            this.items.add(new ConnectionLine<>(regexIn,
                new BoolInput("Regex", node.getRegexEnabled()), null));
            addDisposer(node.getRegexEnabled().onChange(_v -> this.updateResult()));

            ConnectionPointIn<Number> qtyIn = new ConnectionPointIn<>(this, node.getItemQuantity());
            this.items.add(new ConnectionLine<>(qtyIn,
                new IntegerInput("Quantity", node.getItemQuantity()), null));
            addDisposer(node.getItemQuantity().onChange(_v -> this.updateResult()));

            ConnectionPointIn<ComparableNumber.Comparator> cmpIn = new ConnectionPointIn<>(this, node.getQuantityComparator());
            this.items.add(new ConnectionLine<>(cmpIn,
                new EnumInput<>("Comparator", node.getQuantityComparator()), null));
            addDisposer(node.getQuantityComparator().onChange(_v -> this.updateResult()));

        } else if (alertType == InventoryAlert.InventoryAlertType.SLOTS) {
            ConnectionPointIn<Number> qtyIn = new ConnectionPointIn<>(this, node.getItemQuantity());
            this.items.add(new ConnectionLine<>(qtyIn,
                new IntegerInput("Quantity", node.getItemQuantity()), null));
            addDisposer(node.getItemQuantity().onChange(_v -> this.updateResult()));

            ConnectionPointIn<ComparableNumber.Comparator> cmpIn = new ConnectionPointIn<>(this, node.getQuantityComparator());
            this.items.add(new ConnectionLine<>(cmpIn,
                new EnumInput<>("Comparator", node.getQuantityComparator()), null));
            addDisposer(node.getQuantityComparator().onChange(_v -> this.updateResult()));
        }
    }

    private void updateResult() {
        this.inventoryCheck.process();
        if (this.matchView != null) {
            this.matchView.setValue(this.inventoryCheck.getResultOut().getValue());
        }
        this.notifyChange();
    }

    private void rebuildContent() {
        // Remove all conditional controls and the result row (everything from conditionalStartIndex onward)
        while (this.items.getComponentCount() > this.conditionalStartIndex) {
            this.items.remove(this.conditionalStartIndex);
        }

        this.addConditionalControls(this.inventoryCheck);

        // Re-add result row
        ViewInput<Boolean> valueView = new ViewInput<>("Match", this.inventoryCheck.getResultOut().getValue());
        this.items.add(new ConnectionLine<>(null, valueView, this.valueOut));

        this.pack();
        this.revalidate();
        this.repaint();
    }
}

package com.adamk33n3r.runelite.watchdog.ui.nodegraph.logic;

import com.adamk33n3r.nodegraph.nodes.logic.LocationCompare;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.GraphPanel;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.NodePanel;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.ConnectionLine;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.ConnectionPointIn;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.ConnectionPointOut;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.inputs.BoolInput;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.inputs.IntegerInput;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.inputs.ViewInput;
import com.adamk33n3r.runelite.watchdog.ui.panels.PanelUtils;
import lombok.Getter;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;

import javax.swing.*;
import java.awt.*;

@Getter
public class LocationCompareNodePanel extends NodePanel {
    private final ConnectionPointOut<Boolean> resultOut;

    public LocationCompareNodePanel(GraphPanel graphPanel, LocationCompare node, int x, int y, String name, Color color, Client client) {
        super(graphPanel, node, x, y, name, color);

        // Declare resultView early so distance/cardinalOnly callbacks can reference it
        this.resultOut = new ConnectionPointOut<>(this, node.getResult());
        ViewInput<Boolean> resultView = new ViewInput<>("Result", node.getResult().getValue());

        // Input A: WorldPoint with spinners when not connected
        ConnectionPointIn<WorldPoint> inA = new ConnectionPointIn<>(this, node.getA());
        // Wire setConnected so the arrow fills when a connection is made (bypasses ConnectionLine)
        addDisposer(node.getA().onConnectChange(_c -> inA.setConnected(node.getA().isConnected())));
        JPanel pointPanelA = createWorldPointPanel("A", node.getA().getValue(), wp -> node.getA().setValue(wp));
        addDisposer(node.getA().onConnectChange(_c -> setChildrenEnabled(pointPanelA, !node.getA().isConnected())));
        JPanel labeledA = PanelUtils.createLabeledComponent("A", "Location A", pointPanelA);
        this.items.add(wrapWithConnectionPoint(inA, labeledA));

        // Button to set A to current location
        JButton setCurrentA = new JButton("Set A to Current");
        setCurrentA.addActionListener(e -> {
            if (client.getLocalPlayer() != null) {
                WorldPoint wp = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
                node.getA().setValue(wp);
                this.updateSpinners(pointPanelA, wp);
                this.notifyChange();
            }
        });
        this.items.add(setCurrentA);

        // Input B: WorldPoint with spinners when not connected
        ConnectionPointIn<WorldPoint> inB = new ConnectionPointIn<>(this, node.getB());
        // Wire setConnected so the arrow fills when a connection is made (bypasses ConnectionLine)
        addDisposer(node.getB().onConnectChange(_c -> inB.setConnected(node.getB().isConnected())));
        JPanel pointPanelB = createWorldPointPanel("B", node.getB().getValue(), wp -> node.getB().setValue(wp));
        addDisposer(node.getB().onConnectChange(_c -> setChildrenEnabled(pointPanelB, !node.getB().isConnected())));
        JPanel labeledB = PanelUtils.createLabeledComponent("B", "Location B", pointPanelB);
        this.items.add(wrapWithConnectionPoint(inB, labeledB));

        // Button to set B to current location
        JButton setCurrentB = new JButton("Set B to Current");
        setCurrentB.addActionListener(e -> {
            if (client.getLocalPlayer() != null) {
                WorldPoint wp = WorldPoint.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
                node.getB().setValue(wp);
                this.updateSpinners(pointPanelB, wp);
                this.notifyChange();
            }
        });
        this.items.add(setCurrentB);

        // Distance — now a connectable VarInput<Number>
        ConnectionPointIn<Number> distIn = new ConnectionPointIn<>(this, node.getDistance());
        this.items.add(new ConnectionLine<>(distIn, new IntegerInput("Distance", node.getDistance()), null));
        addDisposer(node.getDistance().onChange(_v -> resultView.setValue(node.getResult().getValue())));

        // Cardinal Only — now a connectable VarInput<Boolean>
        ConnectionPointIn<Boolean> cardIn = new ConnectionPointIn<>(this, node.getCardinalOnly());
        this.items.add(new ConnectionLine<>(cardIn, new BoolInput("Cardinal Only", node.getCardinalOnly()), null));
        addDisposer(node.getCardinalOnly().onChange(_v -> resultView.setValue(node.getResult().getValue())));

        // Wire result view to update when A or B input values change
        addDisposer(node.getA().onChange(a -> {
            this.updateSpinners(pointPanelA, a);
            resultView.setValue(node.getResult().getValue());
        }));
        addDisposer(node.getB().onChange(b -> {
            this.updateSpinners(pointPanelB, b);
            resultView.setValue(node.getResult().getValue());
        }));
        this.items.add(new ConnectionLine<>(null, resultView, this.resultOut));

        this.watchDirty(node.getA(), node.getB(), node.getDistance(), node.getCardinalOnly());
        this.pack();
    }

    private JPanel createWorldPointPanel(String label, WorldPoint initial, java.util.function.Consumer<WorldPoint> onUpdate) {
        JPanel panel = new JPanel(new GridLayout(1, 3, 3, 3));
        panel.setOpaque(false);

        int[] coords = { initial.getX(), initial.getY(), initial.getPlane() };

        JSpinner xSpinner = PanelUtils.createSpinner(coords[0], Integer.MIN_VALUE, Integer.MAX_VALUE, 1, val -> {
            coords[0] = val;
            onUpdate.accept(new WorldPoint(coords[0], coords[1], coords[2]));
        });
        JSpinner ySpinner = PanelUtils.createSpinner(coords[1], Integer.MIN_VALUE, Integer.MAX_VALUE, 1, val -> {
            coords[1] = val;
            onUpdate.accept(new WorldPoint(coords[0], coords[1], coords[2]));
        });
        JSpinner planeSpinner = PanelUtils.createSpinner(coords[2], 0, 3, 1, val -> {
            coords[2] = val;
            onUpdate.accept(new WorldPoint(coords[0], coords[1], coords[2]));
        });

        panel.add(xSpinner);
        panel.add(ySpinner);
        panel.add(planeSpinner);
        return panel;
    }

    private void updateSpinners(JPanel panel, WorldPoint wp) {
        Component[] components = panel.getComponents();
        if (components.length >= 3) {
            ((JSpinner) components[0]).setValue(wp.getX());
            ((JSpinner) components[1]).setValue(wp.getY());
            ((JSpinner) components[2]).setValue(wp.getPlane());
        }
    }

    private JPanel wrapWithConnectionPoint(ConnectionPointIn<?> cp, JPanel content) {
        JPanel wrapper = new JPanel(new BorderLayout(5, 5));
        wrapper.setOpaque(false);
        wrapper.add(cp, BorderLayout.WEST);
        wrapper.add(content, BorderLayout.CENTER);
        return wrapper;
    }

    private void setChildrenEnabled(JPanel panel, boolean enabled) {
        for (Component c : panel.getComponents()) {
            c.setEnabled(enabled);
        }
    }
}

package com.adamk33n3r.runelite.watchdog.ui.nodegraph;

import com.adamk33n3r.runelite.watchdog.Util;
import com.adamk33n3r.nodegraph.Node;
import com.adamk33n3r.runelite.watchdog.ui.StretchedStackedLayout;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.NodeConnection;

import com.adamk33n3r.nodegraph.VarInput;
import com.adamk33n3r.nodegraph.VarOutput;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.ConnectionPointIn;
import com.adamk33n3r.runelite.watchdog.ui.nodegraph.connections.ConnectionPointOut;
import lombok.Getter;
import lombok.Setter;

import javax.swing.*;
import javax.swing.border.Border;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

public class NodePanel extends JPanel {
    public static final int PANEL_WIDTH = 300;
    public static final int PANEL_HEIGHT = 200;
    public static final int TITLE_HEIGHT = 20;
    public static final Color NODE_BODY_COLOR = new Color(38, 38, 38);
    private static final int CORNER_ARC = 8;

    protected JPanel items;

    @Getter
    private List<NodeConnection> connections = new ArrayList<>();
    private final List<Runnable> disposers = new ArrayList<>();
    @Getter
    private final GraphPanel graphPanel;
    @Getter
    private final Node node;

    private final Map<VarOutput<?>, ConnectionPointOut<?>> outputRegistry = new IdentityHashMap<>();
    // LinkedHashMap preserves insertion order so "first of type" fallback in ConnectionAutoMatcher is deterministic
    private final Map<VarInput<?>, ConnectionPointIn<?>> inputRegistry = new LinkedHashMap<>();

    public void registerOutputPoint(VarOutput<?> var, ConnectionPointOut<?> cp) {
        outputRegistry.put(var, cp);
    }

    public void registerInputPoint(VarInput<?> var, ConnectionPointIn<?> cp) {
        inputRegistry.put(var, cp);
    }

    @SuppressWarnings("unchecked")
    public <T> ConnectionPointOut<T> getOutputPoint(VarOutput<T> var) {
        return (ConnectionPointOut<T>) outputRegistry.get(var);
    }

    @SuppressWarnings("unchecked")
    public <T> ConnectionPointIn<T> getInputPoint(VarInput<T> var) {
        return (ConnectionPointIn<T>) inputRegistry.get(var);
    }

    public Collection<ConnectionPointIn<?>> getAllInputPoints() {
        return Collections.unmodifiableCollection(inputRegistry.values());
    }

    @Getter
    private final Color titleColor;
    private final String typeName;
    private final JLabel nameLabel;
    private final Border border;
    private JButton collapseButton;

//    protected JPanel inConnectionPoints;
//    protected JPanel outConnectionPoints;

    public NodePanel(GraphPanel graphPanel, Node node, int x, int y, String name, Color color) {
        this.graphPanel = graphPanel;
        this.node = node;
        this.titleColor = color;
        this.typeName = name;
        this.setName(name);
        this.setBounds(x, y, PANEL_WIDTH, PANEL_HEIGHT);
        this.setOpaque(false);
        this.border = BorderFactory.createEmptyBorder(5, 5, 5, 5);
        this.setLayout(new BorderLayout());
        this.nameLabel = new JLabel(name);
//        nameLabel.setForeground(Util.textColorForBG(color));
        nameLabel.setForeground(Color.WHITE);
        nameLabel.setPreferredSize(new Dimension(0, TITLE_HEIGHT));
        nameLabel.setBorder(new EmptyBorder(0, 5, 0, 0));
        JPanel topPanel = new JPanel(new BorderLayout());
        topPanel.setOpaque(false);
        this.collapseButton = new JButton("\u25BC");
        this.collapseButton.setOpaque(false);
        this.collapseButton.setContentAreaFilled(false);
        this.collapseButton.setBorderPainted(false);
        this.collapseButton.setFocusPainted(false);
        this.collapseButton.setForeground(Color.WHITE);
        this.collapseButton.setPreferredSize(new Dimension(20, 20));
        this.collapseButton.setFont(this.collapseButton.getFont().deriveFont(9f));
        this.collapseButton.addActionListener(ev -> this.toggle());
        topPanel.add(this.collapseButton, BorderLayout.WEST);
        topPanel.add(nameLabel, BorderLayout.CENTER);
        JButton button = new JButton("\u00D7");
        button.setOpaque(false);
        button.setContentAreaFilled(false);
        button.setBorderPainted(false);
        button.setFocusPainted(false);
        button.setForeground(Util.textColorForBG(color));
        button.setPreferredSize(new Dimension(20, 20));
        button.addActionListener((ev) -> this.graphPanel.removeNode(this));
        button.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                button.setBackground(new Color(180, 40, 40, 160));
                button.setOpaque(true);
                button.setContentAreaFilled(true);
                button.repaint();
            }
            @Override
            public void mouseExited(MouseEvent e) {
                button.setOpaque(false);
                button.setContentAreaFilled(false);
                button.repaint();
            }
        });
        topPanel.add(button, BorderLayout.EAST);
        this.add(topPanel, BorderLayout.NORTH);

        MouseAdapter onTopAdapter = new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                graphPanel.moveNodeToTop(NodePanel.this);
            }
        };

        JPanel itemsWrapper = new JPanel(new BorderLayout());
        itemsWrapper.setOpaque(false);
        this.items = new JPanel();
        this.items.setOpaque(false);
        itemsWrapper.add(this.items, BorderLayout.NORTH);
        this.items.setBorder(this.border);
        this.items.setLayout(new StretchedStackedLayout(5));
        this.add(itemsWrapper);

        DraggingMouseAdapter draggingMouseAdapter = new DraggingMouseAdapter((start, point) -> {
            point = SwingUtilities.convertPoint(NodePanel.this, point, graphPanel);
            point.translate(-start.x, -start.y);
            point.setLocation(Math.min(Math.max(point.x, 0), graphPanel.getWidth() - PANEL_WIDTH), Math.min(Math.max(point.y, 0), graphPanel.getHeight() - PANEL_HEIGHT));
            this.setLocation(point);
            graphPanel.onNodeMoved(this);
        });
        this.addMouseListener(draggingMouseAdapter);
        this.addMouseMotionListener(draggingMouseAdapter);
        this.addMouseListener(onTopAdapter);
        this.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                if (e.getClickCount() == 2 && e.getY() < TITLE_HEIGHT) {
                    toggle();
                }
            }
        });
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        int w = getWidth();
        int h = getHeight();

        // Dark node body
        g2.setColor(NODE_BODY_COLOR);
        g2.fillRoundRect(0, 0, w, h, CORNER_ARC, CORNER_ARC);

        // Colored title bar — clip to the title region so only the top corners round
        Shape originalClip = g2.getClip();
        g2.setClip(0, 0, w, TITLE_HEIGHT);
        g2.setColor(this.titleColor);
        g2.fillRoundRect(0, 0, w, h, CORNER_ARC, CORNER_ARC);
        g2.setClip(originalClip);

        // Border
        g2.setStroke(new BasicStroke(1.5f));
        g2.setColor(this.titleColor.darker());
        g2.drawRoundRect(0, 0, w - 1, h - 1, CORNER_ARC, CORNER_ARC);

        g2.dispose();
    }

    public void pack() {
        SwingUtilities.invokeLater(() -> {
            Insets borderInsets = this.border.getBorderInsets(this);
            int fullWidth = PANEL_WIDTH + borderInsets.left + borderInsets.right;
            if (this.node.isCollapsed()) {
                this.setBounds(this.getX(), this.getY(), fullWidth, TITLE_HEIGHT);
                this.revalidate();
                this.repaint();
                return;
            }
            int totalHeight = Arrays.stream(this.items.getComponents())
                .mapToInt(c -> c.getPreferredSize().height)
                .sum();
            int padding = 5 * (this.items.getComponentCount() - 1);
            this.setBounds(this.getX(), this.getY(), fullWidth, totalHeight + TITLE_HEIGHT + padding + 2 + borderInsets.top + borderInsets.bottom); // idk why it's +2
            // Not sure why alert node panels need these but notification node panels don't
            this.revalidate();
            this.repaint();
        });
    }

    public void toggle() {
        this.node.setCollapsed(!this.node.isCollapsed());
        this.applyCollapsedState();
        this.notifyChange();
    }

    public void applyCollapsedState() {
        boolean collapsed = this.node.isCollapsed();
        this.items.setVisible(!collapsed);
        this.collapseButton.setText(collapsed ? "▶" : "▼");
        this.pack();
        this.connections.forEach(NodeConnection::recalculateBounds);
        this.graphPanel.repaint();
    }

    public void updateHeaderLabel(String newName) {
        if (newName == null || newName.isBlank()) {
            this.nameLabel.setText(this.typeName);
        } else {
            this.nameLabel.setText(newName + " - " + this.typeName);
        }
    }

    protected void notifyChange() {
        this.graphPanel.notifyChange();
    }

    protected final void watchDirty(VarInput<?>... vars) {
        for (VarInput<?> v : vars) {
            this.addDisposer(v.onChange(_x -> this.notifyChange()));
        }
    }

    public void addConnection(NodeConnection connection) {
        this.connections.add(connection);
    }

    public void removeConnection(NodeConnection connection) {
        this.connections.remove(connection);
    }

    protected void addDisposer(Runnable disposer) {
        this.disposers.add(disposer);
    }

    @Override
    public void removeNotify() {
        super.removeNotify();
        this.disposers.forEach(Runnable::run);
        this.disposers.clear();
    }
}

package com.adamk33n3r.runelite.watchdog.ui.nodegraph;

import com.adamk33n3r.nodegraph.nodes.math.Round;
