        this.items.add(new ConnectionLine<>(null, resultView, this.resultOut));

        this.watchDirty(node.getValue());
        this.pack();
    }
}

package com.adamk33n3r.runelite.watchdog.ui;

import com.adamk33n3r.runelite.watchdog.Displayable;
import com.adamk33n3r.runelite.watchdog.ui.panels.PanelUtils;

import net.runelite.client.ui.DynamicGridLayout;

import lombok.AllArgsConstructor;
import lombok.Getter;

import javax.swing.JComboBox;
import javax.swing.JPanel;
import javax.swing.JSpinner;
import java.awt.Dimension;
import java.util.function.Consumer;

public class ComparableNumber extends JPanel {
    private final JComboBox<Comparator> comparator;
    private final JSpinner number;
    public ComparableNumber(
        int val, Consumer<Integer> onNumChange, int min, int max, int step,
        Comparator comparatorVal, Consumer<Comparator> onComparatorChange
    ) {
        this.comparator = PanelUtils.createSelect(Comparator.values(), comparatorVal, onComparatorChange);
        this.number = PanelUtils.createSpinner(val, min, max, step, onNumChange);

        this.setLayout(new DynamicGridLayout(1, 2, 5, 5));
        this.number.setPreferredSize(new Dimension(70, 0));
        this.add(this.comparator);
        this.add(this.number);
    }

    @Getter
    @AllArgsConstructor
    public enum Comparator implements Displayable {
        EQUALS("==", "Equals"),
        NOT_EQUALS("!=", "Not Equals"),
        LESS_THAN("<", "Less Than"),
        GREATER_THAN(">", "Greater Than"),
        LESS_THAN_OR_EQUALS("<=", "Less Than or Equals"),
        GREATER_THAN_OR_EQUALS(">=", "Greater Than or Equals"),
        ;

        private final String name;
        private final String tooltip;

        public boolean compare(int a, int b) {
            switch (this) {
                case EQUALS:
                    return a == b;
                case NOT_EQUALS:
                    return a != b;
                case LESS_THAN:
                    return a < b;
                case GREATER_THAN:
                    return a > b;
                case LESS_THAN_OR_EQUALS:
                    return a <= b;
                case GREATER_THAN_OR_EQUALS:
                    return a >= b;
                default:
                    return false;
            }
        }

        public Comparator converse() {
            switch (this) {
                case EQUALS:
                    return NOT_EQUALS;
                case NOT_EQUALS:
                    return EQUALS;
                case LESS_THAN:
                    return GREATER_THAN_OR_EQUALS;
                case GREATER_THAN:
                    return LESS_THAN_OR_EQUALS;
                case LESS_THAN_OR_EQUALS:
                    return GREATER_THAN;
                case GREATER_THAN_OR_EQUALS:
                    return LESS_THAN;
                default:
                    throw new IllegalArgumentException();
            }
        }
    }
}

package com.adamk33n3r.runelite.watchdog.ui.panels;

import com.adamk33n3r.runelite.watchdog.AlertManager;
import com.adamk33n3r.runelite.watchdog.WatchdogPlugin;
import com.adamk33n3r.runelite.watchdog.alerts.Alert;
import com.adamk33n3r.runelite.watchdog.alerts.AdvancedAlert;
import com.adamk33n3r.runelite.watchdog.alerts.AlertGroup;
import com.adamk33n3r.runelite.watchdog.alerts.AlertMode;
import com.adamk33n3r.runelite.watchdog.alerts.RegexMatcher;
import com.adamk33n3r.runelite.watchdog.ui.FlatTextArea;
import com.adamk33n3r.runelite.watchdog.ui.PlaceholderTextField;
import com.adamk33n3r.runelite.watchdog.ui.StretchedStackedLayout;

import lombok.Setter;
import net.runelite.client.plugins.info.JRichTextPane;
import net.runelite.client.ui.ColorScheme;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.FocusEvent;
import java.awt.event.FocusListener;
import java.util.Collections;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Abstract base class for alert type-specific content panels.
 * <p>
 * Provides all the {@code add*()} fluent methods used to build the alert's controls.
 * Subclasses implement {@link #buildTypeContent()} for their type-specific UI.
 * <p>
 * Subclasses must set all their own fields and then call {@link #init()} as the
 * final statement in their constructor (after calling {@code super}).
 */
public abstract class AlertContentPanel<T extends Alert> extends JPanel {
    protected T alert;
    protected Runnable onChange;
    protected AlertManager alertManager;
    /**
     * -- SETTER --
     *  Sets a callback invoked after every
     *  call.
     *  Node panels set this to call
     *  after a content rebuild.
     */
    @Setter
    private Runnable onRebuild;
    @Setter
    private Runnable onNameChange;
    @Setter
    private Consumer<String> onNameType;

    protected AlertContentPanel(T alert, Runnable onChange) {
        this.alert = alert;
        this.onChange = onChange;
        this.alertManager = WatchdogPlugin.getInstance().getAlertManager();
        this.setLayout(new StretchedStackedLayout(3));
        this.setBorder(new EmptyBorder(0, 5, 0, 5));
    }

    /**
     * Must be called at the end of each subclass constructor, after all fields are set.
     * Invokes {@link #build()}.
     */
    protected void init() {
        this.build();
    }

    /**
     * Builds the full content: alert defaults followed by type-specific content.
     * Called from {@link #init()} and {@link #rebuild()}.
     */
    public void build() {
        this.addAlertDefaults();
        this.buildTypeContent();
    }

    /**
     * Subclasses implement this to add their type-specific controls to {@code this}.
     * Called by {@link #build()}. Do NOT call {@link #addAlertDefaults()} here.
     */
    public abstract void buildTypeContent();

    /**
     * Clears and rebuilds the content in-place. Fires the optional {@link #setOnRebuild(Runnable)}
     * callback after rebuilding.
     */
    public void rebuild() {
        this.removeAll();
        this.build();
        this.revalidate();
        this.repaint();
        if (this.onRebuild != null) {
            this.onRebuild.run();
        }
    }

    /**
     * Returns {@code true} if the sidebar should add a {@link NotificationsPanel} below this content.
     * Override to return {@code false} for alert types that don't use the notification list
     * (e.g. AdvancedAlert, which uses the node graph instead).
     */
    protected boolean includeNotifications() {
        return true;
    }

    protected boolean hasSubsection() {
        return false;
    }

    protected JComponent getSubsection() {
        return null;
    }

    /**
     * Called when the sidebar's back button is pressed. Override for cleanup
     * (e.g. AdvancedAlert disposes its graph editor frame here).
     */
    protected void onBack() {}

    /**
     * Returns {@code true} if this content panel represents an {@link AlertGroup}.
     * The sidebar wrapper uses this to show an import button instead of a test button.
     */
    protected boolean isAlertGroup() {
        return false;
    }

    // ── Fluent add* methods ────────────────────────────────────────────────────

    public AlertContentPanel<T> addLabel(String label) {
        this.add(new JLabel(label));
        return this;
    }

    public AlertContentPanel<T> addRichTextPane(String text) {
        JRichTextPane richTextPane = new JRichTextPane();
        richTextPane.setContentType("text/html");
        richTextPane.setText(text);
        richTextPane.setForeground(Color.WHITE);
        this.add(richTextPane);
        return this;
    }

    public AlertContentPanel<T> addTextField(String placeholder, String tooltip, String initialValue, Consumer<String> saveAction) {
        PlaceholderTextField textField = new PlaceholderTextField(initialValue);
        textField.setSelectedTextColor(Color.WHITE);
        textField.setSelectionColor(ColorScheme.BRAND_ORANGE_TRANSPARENT);
        textField.setPlaceholder(placeholder);
        textField.setToolTipText(tooltip);
        textField.getDocument().addDocumentListener(new javax.swing.event.DocumentListener() {
            @Override
            public void insertUpdate(javax.swing.event.DocumentEvent e) { fireOnNameType(textField.getText()); }
            @Override
            public void removeUpdate(javax.swing.event.DocumentEvent e) { fireOnNameType(textField.getText()); }
            @Override
            public void changedUpdate(javax.swing.event.DocumentEvent e) {}
        });
        textField.addFocusListener(new FocusListener() {
            @Override
            public void focusGained(FocusEvent e) {
                textField.selectAll();
            }

            @Override
            public void focusLost(FocusEvent e) {
                saveAction.accept(textField.getText());
                alertManager.saveAlerts();
                if (AlertContentPanel.this.onNameChange != null) {
                    AlertContentPanel.this.onNameChange.run();
                }
            }
        });
        this.add(textField);
        return this;
    }

    private void fireOnNameType(String text) {
        if (this.onNameType != null) {
            this.onNameType.accept(text);
        }
    }

    public AlertContentPanel<T> addTextArea(String placeholder, String tooltip, String initialValue, Consumer<String> saveAction) {
        FlatTextArea textArea = PanelUtils.createTextArea(placeholder, tooltip, initialValue, val -> {
            saveAction.accept(val);
            this.alertManager.saveAlerts();
        });
        this.add(textArea);
        return this;
    }

    public AlertContentPanel<T> addSpinner(String name, String tooltip, int initialValue, Consumer<Integer> saveAction) {
        return this.addSpinner(name, tooltip, initialValue, saveAction, 0, Integer.MAX_VALUE, 1);
    }

    public AlertContentPanel<T> addSpinner(String name, String tooltip, int initialValue, Consumer<Integer> saveAction, int min, int max, int step) {
        JSpinner spinner = PanelUtils.createSpinner(initialValue, min, max, step, val -> {
            saveAction.accept(val);
            this.alertManager.saveAlerts();
        });
        this.add(PanelUtils.createLabeledComponent(name, tooltip, spinner));
        return this;
    }

    public <E extends Enum<E>> AlertContentPanel<T> addSelect(String name, String tooltip, Class<E> enumType, E initialValue, Consumer<E> saveAction) {
        JComboBox<E> select = PanelUtils.createSelect(enumType.getEnumConstants(), initialValue, val -> {
            saveAction.accept(val);
            this.alertManager.saveAlerts();
        });
        this.add(PanelUtils.createLabeledComponent(name, tooltip, select));
        return this;
    }

    public AlertContentPanel<T> addCheckbox(String name, String tooltip, boolean initialValue, Consumer<Boolean> saveAction) {
        JCheckBox checkbox = PanelUtils.createCheckbox(name, tooltip, initialValue, val -> {
            saveAction.accept(val);
            this.alertManager.saveAlerts();
        });
        this.add(checkbox);
        return this;
    }

    public AlertContentPanel<T> addInputGroupWithSuffix(JComponent mainComponent, JComponent suffix) {
        return this.addInputGroup(mainComponent, null, Collections.singletonList(suffix));
    }

    public AlertContentPanel<T> addInputGroup(JComponent mainComponent, List<JComponent> prefixes, List<JComponent> suffixes) {
        InputGroup textFieldGroup = new InputGroup(mainComponent)
            .addPrefixes(prefixes)
            .addSuffixes(suffixes);
        this.add(textFieldGroup);
        return this;
    }

    public AlertContentPanel<T> addRegexMatcher(RegexMatcher regexMatcher, String placeholder, String tooltip) {
        return this.addRegexMatcher(regexMatcher, placeholder, tooltip, null);
    }

    public AlertContentPanel<T> addRegexMatcher(RegexMatcher regexMatcher, String placeholder, String tooltip, JComponent suffixAppend) {
        this.add(PanelUtils.createRegexMatcher(regexMatcher, placeholder, tooltip, suffixAppend));
        return this;
    }

    public AlertContentPanel<T> addRegexMatcher(
        Supplier<String> pattern,
        Consumer<String> savePattern,
        Supplier<Boolean> regexEnabled,
        Consumer<Boolean> saveRegexEnabled,
        String placeholder,
        String tooltip,
        JComponent suffixAppend
    ) {
        this.add(PanelUtils.createRegexMatcher(pattern, savePattern, regexEnabled, saveRegexEnabled, placeholder, tooltip, suffixAppend));
        return this;
    }

    // to top area for alert controls
    public AlertContentPanel<T> addSubPanelControl(JPanel sub) {
        this.add(sub);
        return this;
    }

    public AlertContentPanel<T> addButton(String text, String tooltip, PanelUtils.ButtonClickListener clickListener) {
        JButton button = new JButton(text);
        button.setToolTipText(tooltip);
        button.addActionListener(ev -> clickListener.clickPerformed(button, ev.getModifiers()));
        this.add(button);
        return this;
    }

    public AlertContentPanel<T> addIf(Consumer<AlertContentPanel<T>> content, Supplier<Boolean> condition) {
        if (condition.get()) {
            content.accept(this);
        }
        return this;
    }

    /**
     * Adds the standard alert defaults: name field, alert mode select (skipped for AlertGroup),
     * and debounce spinner with reset checkbox.
     */
    public AlertContentPanel<T> addAlertDefaults() {
        JSpinner spinner = PanelUtils.createSpinner(
            this.alert.getDebounceTime(),
            0,
            8640000,
            100,
            val -> {
                this.alert.setDebounceTime(val);
                this.alertManager.saveAlerts();
            }
        );
        JCheckBox checkbox = PanelUtils.createCheckbox("Reset", "Reset the debounce time every time this alert is triggered", this.alert.isDebounceResetTime(), val -> {
            this.alert.setDebounceResetTime(val);
            this.alertManager.saveAlerts();
        });
        JPanel sub = new JPanel(new BorderLayout(5, 5));
        sub.add(spinner);
        sub.add(checkbox, BorderLayout.EAST);
        return this
            .addTextField("Enter the alert name...", "Name of Alert", this.alert.getName(), this.alert::setName)
            .addIf(panel -> panel.addSelect("Alert Mode", "How to handle re-triggering when this alert is already running",
                    AlertMode.class, this.alert.getAlertMode(), this.alert::setAlertMode),
                () -> !(this.alert instanceof AlertGroup) && !(this.alert instanceof AdvancedAlert))
            .addIf(panel -> panel.addSubPanelControl(PanelUtils.createLabeledComponent(
                "Debounce (ms)",
                "How long to wait before allowing this alert to trigger again in milliseconds",
                sub)),
                () -> !(this.alert instanceof AdvancedAlert));
    }
}

package com.adamk33n3r.runelite.watchdog.ui.panels;

import com.adamk33n3r.runelite.watchdog.*;
import com.adamk33n3r.runelite.watchdog.alerts.Alert;
import com.adamk33n3r.runelite.watchdog.notifications.Notification;
import com.adamk33n3r.runelite.watchdog.NotificationType;
import com.adamk33n3r.runelite.watchdog.NotificationCategory;
import com.adamk33n3r.runelite.watchdog.ui.Icons;
import com.adamk33n3r.runelite.watchdog.ui.StretchedStackedLayout;
import com.adamk33n3r.runelite.watchdog.ui.dropdownbutton.DropDownButtonFactory;
import com.adamk33n3r.runelite.watchdog.ui.notifications.panels.NotificationPanel;

import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.components.DragAndDropReorderPane;

import com.google.inject.Injector;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.event.ActionListener;
import java.util.Arrays;
import java.util.Comparator;

@Slf4j
public class NotificationsPanel extends JPanel {
    private Alert alert;

    @Inject
    private NotificationPanelFactory notificationPanelFactory;

    @Inject
    private WatchdogConfig config;

    @Inject
    private AlertManager alertManager;

    @Getter
    private final DragAndDropReorderPane notificationContainer;

    public NotificationsPanel() {
        this.setLayout(new BorderLayout(0, 5));
        this.notificationContainer = new DragAndDropReorderPane();
        this.notificationContainer.addDragListener((c) -> {
            int pos = this.notificationContainer.getPosition(c);
            NotificationPanel notificationPanel = (NotificationPanel) c;
            Notification notification = notificationPanel.getNotification();
//            log.debug("drag listener: " + notification.getType().getName() + " to " + pos);
            notification.getAlert().moveNotificationTo(notification, pos);
            this.alertManager.saveAlerts();
        });
    }

    public void init(Alert alert) {
        this.alert = alert;

        JPopupMenu popupMenu = new JPopupMenu();
        ActionListener actionListener = e -> {
            JMenuItem menuItem = (JMenuItem) e.getSource();
            NotificationType nType = (NotificationType) menuItem.getClientProperty(NotificationType.class);
            this.addPanel(this.createNotification(nType));
            this.notificationContainer.revalidate();
            this.alertManager.saveAlerts();
        };

        if (this.config.enableNotificationCategories()) {
            Arrays.stream(NotificationCategory.values()).forEach(cat -> {
                JMenu subMenu = new JMenu(cat.getName());
                subMenu.setToolTipText(cat.getTooltip());
                popupMenu.add(subMenu);
                popupMenu.putClientProperty(cat.name(), subMenu);
            });
        }
        Arrays.stream(NotificationType.values()).sorted(Comparator.comparing(NotificationType::getName)).forEach(nType -> {
            JMenuItem c = new JMenuItem(nType.getName());
            c.setToolTipText(nType.getTooltip());
            c.putClientProperty(NotificationType.class, nType);
            c.addActionListener(actionListener);
            if (this.config.enableNotificationCategories()) {
                JMenu subMenu = (JMenu) popupMenu.getClientProperty(nType.getCategory().name());
                subMenu.add(c);
            } else {
                popupMenu.add(c);
            }
        });
        JButton addDropDownButton = DropDownButtonFactory.createDropDownButton(Icons.ADD, popupMenu);
        addDropDownButton.setPreferredSize(new Dimension(40, addDropDownButton.getPreferredSize().height));
        addDropDownButton.setToolTipText("Create New Action");
        JPanel headerPanel = new JPanel(new BorderLayout());
        JPanel leftPanel = new JPanel(new DynamicGridLayout(1, 0, 5, 5));
        headerPanel.add(leftPanel, BorderLayout.WEST);
        leftPanel.add(new JLabel("Actions"));
        JButton randomBtn = PanelUtils.createToggleActionButton(
            Icons.DICE_MULTIPLE,
            Icons.DICE_MULTIPLE_HOVER,
            Icons.DICE_MULTIPLE_OFF,
            Icons.DICE_MULTIPLE_OFF_HOVER,
            "Fire all actions in sequence",
            "Fire a random action",
            alert.isRandomNotifications(),
            (btn, mods) -> {
                alert.setRandomNotifications(!alert.isRandomNotifications());
                this.alertManager.saveAlerts();
            }
        );
        leftPanel.add(randomBtn);
        JPanel buttonPanel = new JPanel(new DynamicGridLayout(1, 0));
        buttonPanel.add(addDropDownButton);
        headerPanel.add(buttonPanel, BorderLayout.EAST);
        headerPanel.setBorder(new EmptyBorder(0, 5, 0, 0));

        this.add(headerPanel, BorderLayout.NORTH);

        ScrollablePanel scrollablePanel = new ScrollablePanel(new StretchedStackedLayout(3));
        scrollablePanel.setScrollableWidth(ScrollablePanel.ScrollableSizeHint.FIT);
        scrollablePanel.setScrollableHeight(ScrollablePanel.ScrollableSizeHint.STRETCH);
        scrollablePanel.setScrollableBlockIncrement(ScrollablePanel.VERTICAL, ScrollablePanel.IncrementType.PERCENT, 10);
        scrollablePanel.add(this.notificationContainer);
        JScrollPane scrollPane = new JScrollPane(scrollablePanel, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);
        this.add(scrollPane, BorderLayout.CENTER);

        if (this.alert.getNotifications() != null) {
            for (Notification notification : this.alert.getNotifications()) {
                this.addPanel(notification);
            }
        }
    }

    private void addPanel(Notification notification) {
        PanelUtils.OnRemove removeNotification = (removedPanel) -> {
            WatchdogPlugin.getInstance().getScreenMarkerUtil().finishCreation(true);
            WatchdogPlugin.getInstance().getObjectMarkerManager().turnOffObjectMarkerMode();
            if (this.alert.getNotifications() != null) {
                this.alert.getNotifications().remove(notification);
            }
            this.notificationContainer.remove(removedPanel);
            this.notificationContainer.revalidate();
            this.alertManager.saveAlerts();
        };

        NotificationPanel notificationPanel = this.notificationPanelFactory.createPanel(notification, this, removeNotification);
        if (notificationPanel != null)
            this.notificationContainer.add(notificationPanel);
    }

    private Notification createNotification(NotificationType notificationType) {
        Injector injector = WatchdogPlugin.getInstance().getInjector();
        Notification notification = injector.getInstance(notificationType.getImplClass());
        notification.setAlert(this.alert);
        if (this.alert.getNotifications() != null) {
            this.alert.getNotifications().add(notification);
        }
        return notification;
    }
}

package com.adamk33n3r.runelite.watchdog.ui.panels;

import com.adamk33n3r.runelite.watchdog.alerts.*;
import com.adamk33n3r.runelite.watchdog.ui.alerts.*;

import net.runelite.api.Client;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Creates {@link AlertContentPanel} instances for any alert type.
 * Used by {@link com.adamk33n3r.runelite.watchdog.ui.nodegraph.AlertNodePanel} to populate
 * type-specific controls without duplicating UI code.
 */
@Slf4j
@Singleton
public class AlertPanelContentFactory {
    @Inject private Client client;

    /**
     * Creates the type-specific content panel for {@code alert}.
     * The returned panel can be added to any container (node panel or sidebar).
     *
     * @param alert    the alert to create a content panel for
     * @param onChange callback fired whenever the user changes a value
     * @return the content panel, or {@code null} if the type is not registered
     */
    public AlertContentPanel<?> createContentPanel(Alert alert, Runnable onChange) {
        if (alert instanceof ChatAlert)
            return new GameMessageAlertPanel((ChatAlert) alert, onChange);
        if (alert instanceof PlayerChatAlert)
            return new PlayerChatAlertPanel((PlayerChatAlert) alert, onChange);
        if (alert instanceof SpawnedAlert)
            return new SpawnedAlertPanel((SpawnedAlert) alert, onChange);
        if (alert instanceof StatChangedAlert)
            return new StatChangedAlertPanel((StatChangedAlert) alert, onChange);
        if (alert instanceof InventoryAlert)
            return new InventoryAlertPanel((InventoryAlert) alert, onChange);
        if (alert instanceof LocationAlert)
            return new LocationAlertPanel((LocationAlert) alert, this.client, onChange);
        if (alert instanceof XPDropAlert)
            return new XPDropAlertPanel((XPDropAlert) alert, onChange);
        if (alert instanceof OverheadTextAlert)
            return new OverheadTextAlertPanel((OverheadTextAlert) alert, onChange);
        if (alert instanceof SoundFiredAlert)
            return new SoundFiredAlertPanel((SoundFiredAlert) alert, onChange);
        if (alert instanceof NotificationFiredAlert)
            return new NotificationFiredAlertPanel((NotificationFiredAlert) alert, onChange);
        if (alert instanceof AdvancedAlert)
            return new AdvancedAlertPanel((AdvancedAlert) alert, onChange);

        log.warn("No AlertContentPanel registered for alert type: {}", alert.getClass().getSimpleName());
        return null;
    }
}

package com.adamk33n3r.runelite.watchdog.ui.panels;

import com.adamk33n3r.runelite.watchdog.AlertManager;
import com.adamk33n3r.runelite.watchdog.TriggerType;
import com.adamk33n3r.runelite.watchdog.Util;
import com.adamk33n3r.runelite.watchdog.WatchdogPlugin;
import com.adamk33n3r.runelite.watchdog.alerts.Alert;
import com.adamk33n3r.runelite.watchdog.alerts.AlertGroup;
import com.adamk33n3r.runelite.watchdog.ui.*;

import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.components.DragAndDropReorderPane;

import lombok.Getter;

import javax.annotation.Nullable;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class AlertListPanel extends JPanel {
    private String filterText = "";
    private final List<AlertListItem> alertListItems = new ArrayList<>();
    private final DragAndDropReorderPane dragAndDropReorderPane = new DragAndDropReorderPane();
    @Getter
    private final JScrollPane scrollPane;
    private boolean selectMode = false;
    private final AlertManager alertManager;
    private final Runnable onChange;
    private final List<Alert> alerts;
    private final AlertGroup parent;

    public AlertListPanel(List<Alert> alerts, @Nullable AlertGroup parent, Runnable onChange) {
        this.alerts = alerts;
        this.parent = parent;
        this.onChange = onChange;
        this.alertManager = WatchdogPlugin.getInstance().getAlertManager();
        this.dragAndDropReorderPane.setBackground(ColorScheme.GRAND_EXCHANGE_LIMIT);
        this.dragAndDropReorderPane.addDragListener((c) -> {
            int pos = this.dragAndDropReorderPane.getPosition(c);
            AlertListItem alertListItem = (AlertListItem) c;
            this.alertManager.moveAlertTo(alertListItem.getAlert(), pos);
        });

        this.setLayout(new BorderLayout());

        ScrollablePanel scrollablePanel = new ScrollablePanel(new StretchedStackedLayout(3));
        scrollablePanel.setScrollableWidth(ScrollablePanel.ScrollableSizeHint.FIT);
        scrollablePanel.setScrollableHeight(ScrollablePanel.ScrollableSizeHint.STRETCH);
        scrollablePanel.setScrollableBlockIncrement(ScrollablePanel.VERTICAL, ScrollablePanel.IncrementType.PERCENT, 10);
        scrollablePanel.add(this.dragAndDropReorderPane);
        this.scrollPane = new JScrollPane(scrollablePanel, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED, JScrollPane.HORIZONTAL_SCROLLBAR_AS_NEEDED);

        this.rebuild();
    }

    private void rebuild() {
        this.removeAll();
        this.dragAndDropReorderPane.removeAll();

        SearchBar searchBar = new SearchBar(this::filter);
        Arrays.stream(TriggerType.values()).map(TriggerType::getName).forEach(searchBar.getSuggestionListModel()::addElement);
        JPanel searchWrapper = new JPanel(new BorderLayout());
        searchWrapper.add(searchBar);
        SwingUtilities.invokeLater(() -> {
            searchWrapper.setBorder(new EmptyBorder(0, 0, 2, this.scrollPane.getVerticalScrollBar().isVisible() ? 7 : 0));
        });
        this.add(searchWrapper, BorderLayout.NORTH);
        this.add(this.scrollPane, BorderLayout.CENTER);

        final JPanel multiSelect = new JPanel(new BorderLayout());
        multiSelect.setPreferredSize(new Dimension(0, 25));
        multiSelect.setBorder(new EmptyBorder(0, 10, 0, 0));
        final JPanel toggleGroup = new JPanel(new DynamicGridLayout(1, 2, 3, 3));
        toggleGroup.setBorder(new EmptyBorder(4, 0, 0, 0));
        final ToggleButton selectModeToggle = new ToggleButton("Disable Select Mode", "Enable Select Mode");
        selectModeToggle.setSelected(this.selectMode);
        selectModeToggle.addItemListener((i) -> {
            this.selectMode = selectModeToggle.isSelected();
            this.alertListItems.clear();
            this.rebuild();
        });
        toggleGroup.add(selectModeToggle);
        JLabel selectModeLabel = new JLabel("Select Mode");
        selectModeLabel.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                selectModeToggle.setSelected(!selectModeToggle.isSelected());
                AlertListPanel.this.revalidate();
            }
        });
        toggleGroup.add(selectModeLabel);
        multiSelect.add(toggleGroup, BorderLayout.WEST);

        final JPanel multiSelectActions = new JPanel(new FlowLayout(FlowLayout.RIGHT, 3, 0));
        multiSelectActions.setBorder(new EmptyBorder(6, 0, 0, 0));
        multiSelectActions.add(PanelUtils.createActionButton(Icons.IMPORT, Icons.IMPORT_HOVER, "Move selected Alerts to new Alert Group", (btn, modifiers) -> {
            long count = this.alertListItems.stream()
                .filter(AlertListItem::isSelected)
                .count();
            if (count == 0) {
                return;
            }
            AlertGroup group = this.alertManager.createAlert(AlertGroup.class);
            if (this.parent == null) {
                this.alertManager.addAlert(group, false);
            } else {
                this.parent.getAlerts().add(group);
            }
            this.alertListItems.stream()
                .filter(AlertListItem::isSelected)
                .forEach((ali) -> {
                    this.alertManager.removeAlert(ali.getAlert(), false);
                    ali.getAlert().setParent(group);
                    group.getAlerts().add(ali.getAlert());
                });
            WatchdogPlugin.getInstance().getPanel().openAlert(group);
        })).setEnabled(this.selectMode);
        if (this.parent != null) {
            multiSelectActions.add(PanelUtils.createActionButton(Icons.BACK, Icons.BACK_HOVER, "Move selected Alerts back a level", (btn, modifiers) -> {
                long count = this.alertListItems.stream()
                    .filter(AlertListItem::isSelected)
                    .count();
                if (count == 0) {
                    return;
                }
                AlertGroup alertGroupParent = this.parent.getParent();
                this.alertListItems.stream()
                    .filter(AlertListItem::isSelected)
                    .forEach((ali) -> {
                        this.alertManager.removeAlert(ali.getAlert(), false);
                        ali.getAlert().setParent(alertGroupParent);
                        if (alertGroupParent == null) {
                            this.alertManager.addAlert(ali.getAlert(), false);
                        } else {
                            alertGroupParent.getAlerts().add(ali.getAlert());
                        }
                    });
                WatchdogPlugin.getInstance().getPanel().getMuxer().popState();
                if (alertGroupParent == null) {
                    WatchdogPlugin.getInstance().getPanel().rebuild();
                } else {
                    // pop and reopen in order to rebuild the list
                    WatchdogPlugin.getInstance().getPanel().getMuxer().popState();
                    WatchdogPlugin.getInstance().getPanel().openAlert(alertGroupParent);
                }
            })).setEnabled(this.selectMode);
        }
        multiSelectActions.add(PanelUtils.createActionButton(Icons.EXPORT, Icons.EXPORT_HOVER, "Export selected Alerts", (btn, modifiers) -> {
            List<Alert> selectedAlerts = this.alertListItems.stream()
                .filter(AlertListItem::isSelected)
                .map(AlertListItem::getAlert)
                .collect(Collectors.toList());
            if (selectedAlerts.isEmpty()) {
                return;
            }
            ImportExportDialog importExportDialog = new ImportExportDialog(SwingUtilities.getWindowAncestor(this), selectedAlerts);
            importExportDialog.setVisible(true);
        })).setEnabled(this.selectMode);
        multiSelectActions.add(PanelUtils.createActionButton(Icons.DELETE, Icons.DELETE_HOVER, "Delete selected Alerts", (btn, modifiers) -> {
            long count = this.alertListItems.stream()
                .filter(AlertListItem::isSelected)
                .count();
            if (count == 0) {
                return;
            }
            int result = JOptionPane.showConfirmDialog(this, "Are you sure you want to delete the " + count + " selected alerts?", "Delete?", JOptionPane.YES_NO_OPTION, JOptionPane.ERROR_MESSAGE);
            if (result == JOptionPane.YES_OPTION) {
                this.alertListItems.stream()
                    .filter(AlertListItem::isSelected)
                    .forEach((ali) -> this.alertManager.removeAlert(ali.getAlert()));
                onChange.run();
            }
        })).setEnabled(this.selectMode);
        multiSelect.add(multiSelectActions, BorderLayout.EAST);
        searchWrapper.add(multiSelect, BorderLayout.SOUTH);

        this.alerts.stream()
            .map(alert -> new AlertListItem(WatchdogPlugin.getInstance().getPanel(), this.alertManager, alert, this.dragAndDropReorderPane, onChange))
            .forEach(alertListItem -> {
                alertListItem.setSelectMode(this.selectMode);
                this.alertListItems.add(alertListItem);
                this.dragAndDropReorderPane.add(alertListItem);
            });

        if (!this.filterText.isEmpty()) {
            searchBar.setText(this.filterText);
            this.filter(this.filterText);
        }
    }

    private void filter(String text) {
        this.filterText = text;
        this.dragAndDropReorderPane.removeAll();
        this.alertListItems.stream()
            .filter(alertListItem -> Util.searchText(this.filterText, alertListItem.getAlert().getKeywords()))
            .forEach(this.dragAndDropReorderPane::add);
        this.revalidate();
    }
}

package com.adamk33n3r.runelite.watchdog.ui.panels;

import com.adamk33n3r.runelite.watchdog.AlertManager;
import com.adamk33n3r.runelite.watchdog.notifications.*;
import com.adamk33n3r.runelite.watchdog.notifications.Popup;
import com.adamk33n3r.runelite.watchdog.notifications.objectmarkers.ObjectMarker;
import com.adamk33n3r.runelite.watchdog.ui.notifications.panels.*;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.ui.components.colorpicker.ColorPickerManager;

import lombok.extern.slf4j.Slf4j;

import javax.inject.Inject;
import javax.inject.Singleton;

/**
 * Creates {@link NotificationContentPanel} instances for any notification type, and wraps them
 * in a full {@link NotificationPanel} (sidebar chrome) when needed.
 */
@Slf4j
@Singleton
public class NotificationPanelFactory {
    @Inject private ColorPickerManager colorPickerManager;
    @Inject private ConfigManager configManager;
    @Inject private PluginManager pluginManager;
    @Inject private AlertManager alertManager;

    /**
     * Creates a full {@link NotificationPanel} (title bar, enable toggle, delay, test/delete buttons)
     * for the sidebar. Used by {@link NotificationsPanel#addPanel}.
     */
    public NotificationPanel createPanel(Notification notification, NotificationsPanel parent, PanelUtils.OnRemove onRemove) {
        Runnable onChange = alertManager::saveAlerts;
        NotificationContentPanel<?> content = createContentPanel(notification, onChange);
        if (content == null) {
            return null;
        }

        // ScreenMarkerNotificationPanel needs to hook the onRemove to clean up the overlay.
        PanelUtils.OnRemove effectiveOnRemove = (content instanceof ScreenMarkerNotificationPanel)
            ? ((ScreenMarkerNotificationPanel) content).wrapOnRemove(onRemove)
            : onRemove;

        return new NotificationPanel(content, parent, onChange, effectiveOnRemove);
    }

    /**
     * Creates just the type-specific content panel for the given notification.
     * Node panels add this directly to their {@code items} container.
     *
     * @param notification the notification to create a content panel for
     * @param onChange     callback fired whenever the user changes a value
     * @return the content panel, or {@code null} if the type is not registered
     */
    public NotificationContentPanel<?> createContentPanel(Notification notification, Runnable onChange) {
        if (notification instanceof GameMessage)
            return new MessageNotificationPanel((GameMessage) notification, onChange);
        if (notification instanceof TextToSpeech)
            return new TextToSpeechNotificationPanel((TextToSpeech) notification, onChange);
        if (notification instanceof Sound)
            return new SoundNotificationPanel((Sound) notification, onChange);
        if (notification instanceof SoundEffect)
            return new SoundEffectNotificationPanel((SoundEffect) notification, onChange);
        if (notification instanceof TrayNotification)
            return new MessageNotificationPanel((TrayNotification) notification, onChange);
        if (notification instanceof ScreenFlash)
            return new ScreenFlashNotificationPanel((ScreenFlash) notification, colorPickerManager, onChange);
        if (notification instanceof Overhead)
            return new OverheadNotificationPanel((Overhead) notification, colorPickerManager, onChange);
        if (notification instanceof Overlay)
            return new OverlayNotificationPanel((Overlay) notification, colorPickerManager, onChange);
        if (notification instanceof Popup)
            return new PopupNotificationPanel((Popup) notification, colorPickerManager, onChange);
        if (notification instanceof RequestFocus)
            return new RequestFocusNotificationPanel((RequestFocus) notification, onChange);
        if (notification instanceof NotificationEvent)
            return new MessageNotificationPanel((NotificationEvent) notification, onChange);
        if (notification instanceof DismissOverlay)
            return new DismissOverlayNotificationPanel((DismissOverlay) notification, onChange);
        if (notification instanceof DismissScreenMarker)
            return new DismissScreenMarkerNotificationPanel((DismissScreenMarker) notification, onChange);
        if (notification instanceof DismissObjectMarker)
            return new DismissObjectMarkerNotificationPanel((DismissObjectMarker) notification, onChange);
        if (notification instanceof ScreenMarker)
            return new ScreenMarkerNotificationPanel((ScreenMarker) notification, colorPickerManager, onChange);
        if (notification instanceof ObjectMarker)
            return new ObjectMarkerNotificationPanel((ObjectMarker) notification, colorPickerManager, onChange);
        if (notification instanceof Dink)
            return new DinkNotificationPanel((Dink) notification, configManager, onChange);
        if (notification instanceof ShortestPath)
            return new ShortestPathNotificationPanel((ShortestPath) notification, configManager, onChange);
        if (notification instanceof PluginMessage)
            return new PluginMessageNotificationPanel((PluginMessage) notification, onChange);
        if (notification instanceof PluginToggle)
            return new PluginToggleNotificationPanel((PluginToggle) notification, pluginManager, onChange);
        if (notification instanceof AlertToggle)
            return new AlertToggleNotificationPanel((AlertToggle) notification, onChange);
        if (notification instanceof Counter)
            return new CounterNotificationPanel((Counter) notification, onChange);

        log.warn("No NotificationContentPanel registered for type: {}", notification.getClass().getSimpleName());
        return null;
    }
}

